// circle_racer.cxx  (версия с гаражом, режимом FORMULA, пит-лейном и игрой по локальной сети)
// Гонка на SDL3 (портрет). Машинки — PNG-спрайты, ВСТРОЕНЫ прямо в код (массивы байт),
// отдельные файлы и библиотеки (SDL_image) не нужны. Фон вокруг машинки прозрачный.
//
// Что внутри:
//   * Гараж (кнопка под профилем): вкладки STANDARD RACES (цвет машины) и FORMULA (три формульные
//     машины: фиолетовая, красная, зелёная); выбор запоминается в профиле игрока
//   * Режим FORMULA (выбрана формульная машина): разгон быстрее, максимальная скорость та же;
//     бот становится синей формульной машиной; после 4-го и 8-го круга появляется красное
//     «PIT LANE NEEDED» и кнопка PIT под тормозом: заезд в пит-лейн убирает машину с трассы на 5 с
//     и сбрасывает износ шин. Без пит-стопа макс. скорость падает на 10% за каждый следующий круг.
//     Бот заезжает в пит-лейн сам (на тех же кругах), в остальном ведёт себя как обычно
//   * ИГРА ПО ЛОКАЛЬНОЙ СЕТИ (Wi-Fi): после входа — выбор «PLAY VS BOT» или «LOCAL NETWORK».
//     Сеть: список доступных комнат + создание своей (тип гонки STANDARD/FORMULA, 2/3/4 игрока,
//     маршрут из всех карт). Когда комната заполнена, игрокам выдаются цвета машин и начинается
//     гонка. Работает на обычных UDP-сокетах (SDL3_net не нужна). Для Android нужно разрешение
//     INTERNET: если комнаты не создаются («NETWORK ERROR»), добавьте в шаг 5 workflow строку
//       sed -i 's#<application#<uses-permission android:name="android.permission.INTERNET" />\n    <application#' proj/app/src/main/AndroidManifest.xml
//     (если такого разрешения в манифесте шаблона SDL ещё нет).
//   * Регистрация/вход (имя + пароль) на SQLite; профиль: лучшее время и победы по каждой карте
//   * Главное меню с выбором карты: КРУГ, ORBITS, ЛАБИРИНТ, ВОРОНКА (FUNNEL), RAYS и HOURGLASS;
//     карты листаются страницами (по 3 на странице) — новые карты добавляются в BuildMaps()
//   * Любая карта — набор стенок (внешний борт + острова) и траектория бота
//   * Синий бот едет по своей траектории на каждой карте с одной и той же скоростью
//   * Кто первым проедет TARGET_LAPS кругов — выигрывает; после финиша игра возвращается в меню
//   * Скольжение по бортикам: при касании под малым углом машина едет вдоль борта,
//     скорость скольжения зависит от набранной скорости (разгона) и угла касания
//
// Управление:
//   Меню:   тап по карте; листать — свайп вверх/вниз, стрелки < >, колесо мыши, A/D или ←/→;
//           клавиши 1..9 — быстрый выбор карты, W/S (↑/↓) + Enter
//   Гонка:  тач — круглый руль слева, зелёная кнопка — газ, красная — тормоз, MENU — выход в меню
//           клавиатура — A/D или ←→ руль, W/↑ газ, S/↓ тормоз, P — пит-лейн (Formula), R рестарт, Esc — в меню

