// Новые машины (с индекса CAR_FIRST_LOCKED) открываются на ранге SKILLED RACER — после CAR_UNLOCK_WINS побед
static const int CAR_FIRST_LOCKED = 3;
static const int CAR_UNLOCK_WINS  = 12;   // жёлтая и оранжевая — ранг SKILLED RACER
static const int CAR_FINAL_INDEX  = 5;    // бирюзовая (последняя) — только ранг TOP RACER
static const int CAR_FINAL_WINS   = 24;
// Карты CORNERS и WRISTWATCH открываются на ранге SKILLED RACER (MAP_LOCK_WINS побед)
static int PlayerTotalWins();
static const int MAP_FIRST_LOCKED = 6;
static const int MAP_LOCK_WINS    = 12;
static int  MapUnlockWins(int idx) { return idx >= MAP_FIRST_LOCKED ? MAP_LOCK_WINS : 0; }
static bool MapLocked(int idx) { return PlayerTotalWins() < MapUnlockWins(idx); }
static int CarUnlockWins(int idx) { return idx >= CAR_FINAL_INDEX ? CAR_FINAL_WINS : (idx >= CAR_FIRST_LOCKED ? CAR_UNLOCK_WINS : 0); }
static int PlayerTotalWins();
static const int CAR_COLOR_DEFAULT = 1;           // красная — как раньше
static int   carColor   = CAR_COLOR_DEFAULT;      // выбранный цвет текущего игрока
static int   garageTab  = 0;                      // 0 — STANDARD RACES, 1 — FORMULA

// Формульные машины (вкладка FORMULA). Новая: добавьте PNG, имя и увеличьте FORM_CARS.
static const int FORM_CARS = 6;
static const char* const FORM_NAMES[FORM_CARS] = { "PURPLE", "RED", "GREEN", "YELLOW", "ORANGE", "TEAL" };
static int carFormula = -1;                       // -1 — обычная машина; 0..FORM_CARS-1 — выбрана формульная
static const int CAR_FORMULA_BASE = 10;           // в профиле формульная машина хранится как 10 + номер

static bool FormulaMode() { return carFormula >= 0; }
static int  CarChoiceCode() { return carFormula >= 0 ? CAR_FORMULA_BASE + carFormula : carColor; }
static bool CarLocked(int idx) { return PlayerTotalWins() < CarUnlockWins(idx); }
static void ApplyCarChoice(int v) {
    if (v >= CAR_FORMULA_BASE && v < CAR_FORMULA_BASE + FORM_CARS) {
        carFormula = v - CAR_FORMULA_BASE;
        if (CarLocked(carFormula)) carFormula = 0;     // машина ещё не открыта
    } else {
        carFormula = -1;
        carColor = (v >= 0 && v < CAR_COLORS) ? v : CAR_COLOR_DEFAULT;
        if (CarLocked(carColor)) carColor = CAR_COLOR_DEFAULT;
    }
}

// ====================== Карты ======================
struct Vec2 { float x, y; };
struct Seg  { float ax, ay, bx, by; };
struct Vec3 { float x, y, a; };

struct TrackMap {
    const char* name = "";
    const char* desc = "";
    std::vector<std::vector<Vec2>> loops;  // [0] — внешний борт, остальные — острова
    std::vector<std::vector<Vec2>> lines;  // отдельные тонкие стенки (открытые ломаные)
    std::vector<std::vector<Vec2>> fills;  // закрашенные области без собственных стенок (залитые «луны»)
    std::vector<Seg> segs;                 // все стенки (для столкновений)
    std::vector<Vec3> boosts;              // ускорители: x, y, угол стрелки (рад.)
    std::vector<Vec2> frame;               // (необязательно) внешний контур толстой рамки борта
    std::vector<Vec2> path;                // траектория бота / «прогресс» игрока (по часовой стрелке)
    float pathLen  = 1.0f;
    float pathStep = 1.0f;
    Vec2  gateA{0, 0}, gateB{0, 0};        // линия старта/финиша
};

