// ====================== Вспомогательные ======================
static float NormalizeAngle(float a) {
    while (a >  SDL_PI_F) a -= 2.0f * SDL_PI_F;
    while (a < -SDL_PI_F) a += 2.0f * SDL_PI_F;
    return a;
}

static float Length(float x, float y) {
    return std::sqrt(x * x + y * y);
}

// ---------- построение геометрии ----------
static std::vector<Vec2> MakeCircle(float cx, float cy, float r, int n, float a0) {
    std::vector<Vec2> v;
    for (int i = 0; i < n; ++i) {
        float a = a0 + 2.0f * SDL_PI_F * i / n;
        v.push_back({ cx + std::cos(a) * r, cy + std::sin(a) * r });
    }
    return v;
}

static std::vector<Vec2> ScaleAbout(const std::vector<Vec2>& v, Vec2 c, float k) {
    std::vector<Vec2> o;
    for (const Vec2& p : v) o.push_back({ c.x + (p.x - c.x) * k, c.y + (p.y - c.y) * k });
    return o;
}

// Многоугольник со скруглёнными углами (квадратичная кривая Безье в каждом углу)
static std::vector<Vec2> RoundedPolygon(const std::vector<Vec2>& v, float cut, int seg) {
    std::vector<Vec2> out;
    int n = (int)v.size();
    for (int i = 0; i < n; ++i) {
        Vec2 P = v[(i + n - 1) % n], V = v[i], N = v[(i + 1) % n];
        auto toward = [](Vec2 A, Vec2 B, float d) {
            float dx = B.x - A.x, dy = B.y - A.y;
            float L = std::sqrt(dx * dx + dy * dy);
            d = std::min(d, L * 0.5f);
            return Vec2{ A.x + dx / L * d, A.y + dy / L * d };
        };
        Vec2 A = toward(V, P, cut);
        Vec2 B = toward(V, N, cut);
        for (int k = 0; k <= seg; ++k) {
            float t = (float)k / seg;
            float a = (1 - t) * (1 - t), b = 2 * (1 - t) * t, c = t * t;
            out.push_back({ a * A.x + b * V.x + c * B.x, a * A.y + b * V.y + c * B.y });
        }
    }
    return out;
}

static float PolyArea(const std::vector<Vec2>& p) {
    float s = 0.0f;
    int n = (int)p.size();
    for (int i = 0; i < n; ++i) {
        const Vec2& a = p[i];
        const Vec2& b = p[(i + 1) % n];
        s += a.x * b.y - b.x * a.y;
    }
    return s * 0.5f;
}

// Расстояние от точки o вдоль луча d до ближайшей стенки
static float RayDist(Vec2 o, Vec2 d, const std::vector<Seg>& segs, float maxD) {
    float best = maxD;
    for (const Seg& s : segs) {
        float ex = s.bx - s.ax, ey = s.by - s.ay;
        float den = d.x * ey - d.y * ex;
        if (std::abs(den) < 1e-6f) continue;
        float wx = s.ax - o.x, wy = s.ay - o.y;
        float t = (wx * ey - wy * ex) / den;
        float u = (wx * d.y - wy * d.x) / den;
        if (t > 0.01f && u >= 0.0f && u <= 1.0f && t < best) best = t;
    }
    return best;
}

// Достраивает карту: сегменты стен, равномерную траекторию (по часовой стрелке) и линию финиша
static void FinalizeMap(TrackMap& m, std::vector<Vec2> raw, Vec2 gatePos) {
    if (PolyArea(raw) < 0.0f) std::reverse(raw.begin(), raw.end());

    // равномерная передискретизация (шаг ≈ 4 px)
    std::vector<Vec2> P = raw;
    P.push_back(raw[0]);
    std::vector<float> cum(P.size(), 0.0f);
    for (size_t i = 1; i < P.size(); ++i)
        cum[i] = cum[i - 1] + Length(P[i].x - P[i - 1].x, P[i].y - P[i - 1].y);
    float L = cum.back();
    int N = std::max(40, (int)std::lround(L / 4.0f));

    std::vector<Vec2> out(N);
    size_t j = 0;
    for (int k = 0; k < N; ++k) {
        float s = L * k / N;
        while (j + 2 < P.size() && cum[j + 1] < s) ++j;
        float sl = cum[j + 1] - cum[j];
        float t = (sl > 1e-6f) ? (s - cum[j]) / sl : 0.0f;
        out[k] = { P[j].x + (P[j + 1].x - P[j].x) * t, P[j].y + (P[j + 1].y - P[j].y) * t };
    }

    // сдвигаем начало траектории к линии финиша
    int best = 0;
    float bd = 1e9f;
    for (int i = 0; i < N; ++i) {
        float d = Length(out[i].x - gatePos.x, out[i].y - gatePos.y);
        if (d < bd) { bd = d; best = i; }
    }
    std::rotate(out.begin(), out.begin() + best, out.end());

    m.path = out;
    m.pathLen = L;
    m.pathStep = L / N;

    // стенки
    m.segs.clear();
    for (const auto& loop : m.loops) {
        int n = (int)loop.size();
        for (int i = 0; i < n; ++i) {
            const Vec2& a = loop[i];
            const Vec2& b = loop[(i + 1) % n];
            m.segs.push_back({ a.x, a.y, b.x, b.y });
        }
    }

    for (const auto& line : m.lines)
        for (size_t i = 0; i + 1 < line.size(); ++i)
            m.segs.push_back({ line[i].x, line[i].y, line[i + 1].x, line[i + 1].y });

    // линия финиша: от траектории поперёк трассы до стенок с обеих сторон
    Vec2 t = { out[1].x - out[N - 1].x, out[1].y - out[N - 1].y };
    float tl = Length(t.x, t.y);
    t.x /= tl; t.y /= tl;
    Vec2 n = { -t.y, t.x };
    float dPlus  = RayDist(gatePos, n, m.segs, 80.0f);
    float dMinus = RayDist(gatePos, { -n.x, -n.y }, m.segs, 80.0f);
    m.gateA = { gatePos.x - n.x * (dMinus - 3.0f), gatePos.y - n.y * (dMinus - 3.0f) };
    m.gateB = { gatePos.x + n.x * (dPlus  - 3.0f), gatePos.y + n.y * (dPlus  - 3.0f) };
}

// Точки дуги окружности от угла a0 до a1 (в градусах; экранные координаты, y вниз), n отрезков
static std::vector<Vec2> ArcPoints(float cx, float cy, float r, float a0, float a1, int n) {
    std::vector<Vec2> v;
    for (int i = 0; i <= n; ++i) {
        float a = (a0 + (a1 - a0) * i / n) * SDL_PI_F / 180.0f;
        v.push_back({ cx + std::cos(a) * r, cy + std::sin(a) * r });
    }
    return v;
}

// Тонкая стенка-«луч» от a до b толщиной 2*hw — закрашенный четырёхугольник
static std::vector<Vec2> ThickSegment(Vec2 a, Vec2 b, float hw) {
    float dx = b.x - a.x, dy = b.y - a.y;
    float L = std::sqrt(dx * dx + dy * dy);
    float nx = -dy / L * hw, ny = dx / L * hw;
    return { { a.x + nx, a.y + ny }, { b.x + nx, b.y + ny }, { b.x - nx, b.y - ny }, { a.x - nx, a.y - ny } };
}

static float PathHeading(const TrackMap& m, float s);

static void BuildMaps() {
    // ---------- 0. КРУГ ----------
    {
        TrackMap& m = trackMaps[0];
        m.name = "CIRCLE";
        m.desc = "Classic ring";
        const float cx = 180.0f, cy = 205.0f;
        m.loops.push_back(MakeCircle(cx, cy, 168.0f, 96, -SDL_PI_F * 0.5f));
        m.loops.push_back(MakeCircle(cx, cy, 58.0f, 64, -SDL_PI_F * 0.5f));
        FinalizeMap(m, MakeCircle(cx, cy, 113.0f, 120, -SDL_PI_F * 0.5f), { cx, cy - 113.0f });
    }

    // ---------- 1. ORBITS (орбиты) ----------
    // Круглая арена с круглым островом в центре. К внешнему борту прижаты четыре полукруглые
    // «луны»: две большие слева и справа и две маленькие (сверху справа и снизу слева).
    // Трасса — слегка вытянутая «орбита», которая огибает луны.
    {
        TrackMap& m = trackMaps[1];
        m.name = "ORBITS";
        m.desc = "Orbiting bumps";
        const float cx = 180.0f, cy = 203.0f, R = 161.6f;
        m.loops.push_back(MakeCircle(cx, cy, R, 112, -SDL_PI_F * 0.5f));
        m.loops.push_back(MakeCircle(cx, cy, 44.0f, 64, -SDL_PI_F * 0.5f));

        // луна с центром (bx,by) и радиусом rb: часть её круга внутри арены
        auto Bump = [&](float bx, float by, float rb) {
            float dx = bx - cx, dy = by - cy;
            float d = std::sqrt(dx * dx + dy * dy);
            float ux = dx / d, uy = dy / d;
            float a = (R * R - rb * rb + d * d) / (2.0f * d);
            float h = std::sqrt(R * R - a * a);
            Vec2 P1 = { cx + ux * a - uy * h, cy + uy * a + ux * h };
            Vec2 P2 = { cx + ux * a + uy * h, cy + uy * a - ux * h };
            auto wrap = [](float v) {
                while (v > SDL_PI_F) v -= 2.0f * SDL_PI_F;
                while (v < -SDL_PI_F) v += 2.0f * SDL_PI_F;
                return v;
            };
            float f1 = std::atan2(P1.y - by, P1.x - bx), f2 = std::atan2(P2.y - by, P2.x - bx);
            float f0 = std::atan2(cy - by, cx - bx);
            float delta = wrap(f2 - f1);
            if (std::cos(f1 + delta * 0.5f - f0) < 0.0f) delta += (delta > 0.0f ? -2.0f : 2.0f) * SDL_PI_F;
            std::vector<Vec2> arc;
            const int N = 18;
            for (int i = 0; i <= N; ++i) {
                float f = f1 + delta * i / N;
                arc.push_back({ bx + std::cos(f) * rb, by + std::sin(f) * rb });
            }
            m.lines.push_back(arc);
            // заливка: дуга луны + дуга внешнего борта обратно от P2 к P1
            std::vector<Vec2> fill = arc;
            float g2 = std::atan2(P2.y - cy, P2.x - cx), g1 = std::atan2(P1.y - cy, P1.x - cx);
            float dg = wrap(g1 - g2);
            for (int i = 1; i < 10; ++i) {
                float g = g2 + dg * i / 10.0f;
                fill.push_back({ cx + std::cos(g) * R, cy + std::sin(g) * R });
            }
            m.fills.push_back(fill);
        };
        Bump(27.4f, 203.0f, 46.0f);
        Bump(332.6f, 203.0f, 46.0f);
        Bump(261.0f, 68.6f, 25.0f);
        Bump(99.0f, 337.4f, 25.0f);

        std::vector<Vec2> path;
        for (int i = 0; i < 120; ++i) {
            float t = 2.0f * SDL_PI_F * i / 120.0f;
            float r = 93.0f - 18.0f * std::cos(2.0f * t);
            path.push_back({ cx + std::cos(t) * r, cy + std::sin(t) * r });
        }
        float tg = 31.0f * SDL_PI_F / 180.0f;
        float rg = 93.0f - 18.0f * std::cos(2.0f * tg);
        FinalizeMap(m, path, { cx + std::cos(tg) * rg, cy + std::sin(tg) * rg });
    }

    // ---------- 2. LABYRINTH ----------
    // Прямоугольная коробка; внутри — П-образная стенка (открытая сверху) и перегородка,
    // свисающая с верхней стены. Круг идёт змейкой: по нижнему коридору, вверх по боковому,
    // вниз в «правую половину» П, под перегородкой в «левую половину», вверх и по другому
    // боковому коридору обратно к финишу (белая линия слева внизу).
    // Координаты заданы в пикселях макета (1449x2576) и переводятся в логические.
    {
        TrackMap& m = trackMaps[2];
        m.name = "LABYRINTH";
        m.desc = "Twisting maze";
        const float S = 0.97f;
        auto L = [&](float x, float y) {
            return Vec2{ 180.0f + (x / 4.025f - 186.5f) * S, 76.0f + (y / 4.025f - 79.8f) * S };
        };

        m.frame = { L(139, 321), L(1363, 321), L(1363, 1544), L(139, 1544) };
        m.loops.push_back({ L(163, 345), L(1338, 345), L(1338, 1520), L(163, 1520) });           // коробка
        m.loops.push_back({ L(431, 635), L(452, 635), L(452, 1162), L(1043, 1162),               // П-образная стенка
                            L(1043, 645), L(1065, 645), L(1065, 1187), L(431, 1187) });
        m.loops.push_back({ L(729, 345), L(751, 345), L(751, 868), L(729, 868) });               // перегородка

        std::vector<Vec2> ctrl = {
            L(297, 1353), L(1201, 1353), L(1201, 490), L(897, 490),
            L(897, 1015), L(590, 1015), L(590, 490), L(297, 490)
        };
        std::vector<Vec2> path = RoundedPolygon(ctrl, 120.0f / 4.025f * S, 10);
        FinalizeMap(m, path, L(444, 1353));
    }

    // ---------- 3. FUNNEL (воронка) ----------
    // Карта по рисунку: на всю ширину экрана коробка со срезанными нижними углами (две тонкие
    // диагональные стенки), посередине остров — перевёрнутый скруглённый треугольник с широкой
    // «шляпой»-перекладиной сверху. Едем по часовой стрелке вокруг острова, финиш — под его носиком.
    // Координаты — в пикселях макета (1449x2576), сдвинуты на 13 px вверх, чтобы нижний борт
    // оказался над панелью управления.
    {
        TrackMap& m = trackMaps[3];
        m.name = "FUNNEL";
        m.desc = "Around the funnel";
        auto L = [](float x, float y) { return Vec2{ x / 4.025f, y / 4.025f - 13.0f }; };

        m.frame = { L(0, 365), L(1449, 365), L(1449, 1550), L(0, 1550) };
        m.loops.push_back({ L(20, 388), L(1432, 388), L(1432, 1525), L(20, 1525) });   // коробка
        m.lines.push_back({ L(20, 1127), L(260, 1525) });                              // срез слева внизу
        m.lines.push_back({ L(1432, 1127), L(1187, 1525) });                           // срез справа внизу

        // остров: скруглённый перевёрнутый треугольник + перекладина сверху
        const int SEG = 8;
        std::vector<Vec2> tri = { L(432, 738), L(1018, 738), L(725, 1240) };
        std::vector<Vec2> rp = RoundedPolygon(tri, 75.0f / 4.025f, SEG);
        std::vector<Vec2> island = { L(355, 709), L(1094, 709), L(1094, 738) };
        island.insert(island.end(), rp.begin() + (SEG + 1), rp.end());          // углы справа-сверху и носик
        island.insert(island.end(), rp.begin(), rp.begin() + (SEG + 1));        // угол слева-сверху
        island.push_back(L(355, 738));
        m.loops.push_back(island);

        std::vector<Vec2> ctrl = {
            L(190, 548), L(1259, 548), L(1259, 1000), L(1050, 1380), L(400, 1380), L(190, 1000)
        };
        std::vector<Vec2> path = RoundedPolygon(ctrl, 200.0f / 4.025f, 10);
        FinalizeMap(m, path, L(725, 1380));
    }

    // ---------- 4. RAYS (лучи) ----------
    // Карта по рисунку: коробка на всю ширину экрана, посередине остров — прямоугольник
    // со скруглёнными правым-верхним и левым-нижним углами. От острова (в левом-верхнем и
    // правом-нижнем углах) в трассу выступают диагональные «лучи», а из двух других углов
    // коробки навстречу им торчат такие же лучи. Едем по часовой стрелке, огибая кончики лучей.
    // Финиш — вертикальная линия в нижнем коридоре, справа под островом.
    {
        TrackMap& m = trackMaps[4];
        m.name = "RAYS";
        m.desc = "Diagonal spikes";
        auto L = [](float x, float y) { return Vec2{ x / 4.025f, y / 4.025f - 13.0f }; };
        auto Conv = [&](std::vector<Vec2> v) { for (Vec2& p : v) p = L(p.x, p.y); return v; };

        m.frame = Conv({ { 0, 365 }, { 1449, 365 }, { 1449, 1550 }, { 0, 1550 } });
        m.loops.push_back(Conv({ { 20, 388 }, { 1432, 388 }, { 1432, 1525 }, { 20, 1525 } }));   // коробка

        // остров: острые углы слева-сверху и справа-снизу, скруглены справа-сверху и слева-снизу
        std::vector<Vec2> isl = { { 447, 730 }, { 853, 730 } };
        std::vector<Vec2> a1 = ArcPoints(853, 880, 150, -90, 0, 10);
        isl.insert(isl.end(), a1.begin() + 1, a1.end());
        isl.push_back({ 1003, 1160 });
        isl.push_back({ 597, 1160 });
        std::vector<Vec2> a2 = ArcPoints(597, 1010, 150, 90, 180, 10);
        isl.insert(isl.end(), a2.begin() + 1, a2.end());
        m.loops.push_back(Conv(isl));

        // четыре луча (толщина 26 px макета)
        const float hw = 13.0f;
        m.loops.push_back(Conv(ThickSegment({ 470, 748 }, { 335, 642 }, hw)));      // из угла острова слева-сверху
        m.loops.push_back(Conv(ThickSegment({ 980, 1142 }, { 1112, 1248 }, hw)));   // из угла острова справа-снизу
        m.loops.push_back(Conv(ThickSegment({ 1426, 393 }, { 1228, 558 }, hw)));    // из угла коробки справа-сверху
        m.loops.push_back(Conv(ThickSegment({ 26, 1519 }, { 222, 1358 }, hw)));     // из угла коробки слева-снизу

        std::vector<Vec2> ctrl = Conv({ { 985, 1385 }, { 500, 1385 }, { 356, 1237 }, { 190, 1050 }, { 190, 520 },
                                        { 900, 520 }, { 1090, 640 }, { 1260, 830 }, { 1260, 1385 } });
        FinalizeMap(m, RoundedPolygon(ctrl, 90.0f / 4.025f, 10), L(985, 1385));
    }

    // ---------- 5. HOURGLASS (песочные часы) ----------
    // Карта по рисунку: посередине — «песочные часы» на боку: две вертикальные стенки, а сверху и
    // снизу вырезаны полукруглые чаши (открытые вверх и вниз). Из верхней и нижней стен в чаши
    // свисают полукруглые выступы. Трасса идёт по кругу: левый коридор вверх, затем S-образно
    // над левым «рогом», внутрь верхней чаши под выступом и над правым «рогом», вниз по правому
    // коридору и так же через нижнюю чашу. Финиш — горизонтальная линия в левом коридоре.
    {
        TrackMap& m = trackMaps[5];
        m.name = "HOURGLASS";
        m.desc = "Curved channels";
        auto L = [](float x, float y) { return Vec2{ x / 4.025f, y / 4.025f - 13.0f }; };
        auto Conv = [&](std::vector<Vec2> v) { for (Vec2& p : v) p = L(p.x, p.y); return v; };

        m.frame = Conv({ { 0, 365 }, { 1449, 365 }, { 1449, 1550 }, { 0, 1550 } });
        m.loops.push_back(Conv({ { 20, 388 }, { 1432, 388 }, { 1432, 1525 }, { 20, 1525 } }));   // коробка

        // центральная фигура: прямоугольник 393..1066 x 578..1300 с полукруглыми вырезами сверху и снизу
        std::vector<Vec2> body = { { 393, 578 } };
        std::vector<Vec2> topCup = ArcPoints(729, 578, 311, 180, 0, 16);
        body.insert(body.end(), topCup.begin(), topCup.end());
        body.push_back({ 1066, 578 });
        body.push_back({ 1066, 1300 });
        std::vector<Vec2> botCup = ArcPoints(729, 1300, 311, 0, -180, 16);
        body.insert(body.end(), botCup.begin(), botCup.end());
        body.push_back({ 393, 1300 });
        m.loops.push_back(Conv(body));

        // выступы-полукруги от верхней и нижней стен (внутри пустые — закрыты стеной)
        m.lines.push_back(Conv(ArcPoints(730, 388, 190, 180, 0, 16)));
        m.lines.push_back(Conv(ArcPoints(730, 1525, 190, 180, 360, 16)));

        std::vector<Vec2> ctrl = Conv({
            { 206, 480 }, { 470, 490 }, { 600, 680 }, { 730, 740 }, { 860, 680 }, { 990, 490 }, { 1250, 480 },
            { 1250, 1433 }, { 990, 1423 }, { 860, 1233 }, { 730, 1173 }, { 600, 1233 }, { 470, 1423 }, { 206, 1433 }
        });
        FinalizeMap(m, RoundedPolygon(ctrl, 70.0f / 4.025f, 10), L(206, 940));
    }

    // ---------- 6. CORNERS (углы) ----------
    // Квадратная арена: из верхней стены свисает полукруг слева, из нижней поднимается полукруг справа,
    // посередине — квадратный остров. Трасса идёт кольцом вокруг острова, финиш — слева от острова.
    {
        TrackMap& m = trackMaps[6];
        m.name = "CORNERS";
        m.desc = "Arcs and a block";
        const float k = 282.0f / 949.0f;
        auto L = [k](float x, float y) { return Vec2{ 39.0f + (x - 88.0f) * k, 84.0f + (y - 262.0f) * k }; };
        auto Conv = [&](std::vector<Vec2> v) { for (Vec2& p : v) p = L(p.x, p.y); return v; };

        m.frame = Conv({ { 68, 242 }, { 1057, 242 }, { 1057, 1231 }, { 68, 1231 } });
        m.loops.push_back(Conv({ { 88, 262 }, { 1037, 262 }, { 1037, 1211 }, { 88, 1211 } }));
        m.loops.push_back(Conv({ { 483, 657 }, { 643, 657 }, { 643, 817 }, { 483, 817 } }));
        m.lines.push_back(Conv(ArcPoints(353, 262, 255, 0, 180, 24)));      // полукруг сверху слева
        m.lines.push_back(Conv(ArcPoints(771, 1211, 255, 180, 360, 24)));   // полукруг снизу справа

        std::vector<Vec2> ctrl = Conv({ { 290, 886 }, { 290, 592 }, { 880, 592 }, { 880, 886 } });
        FinalizeMap(m, RoundedPolygon(ctrl, 90.0f * k, 10), L(290, 737));
    }

    // ---------- 7. WRISTWATCH (наручные часы) ----------
    // Корпус часов: прямоугольник с выпуклыми дугами по бокам, посередине — овальный остров.
    // Две жёлтые стрелки-ускорителя: на 3 секунды добавляют +20 к скорости (даже на максимуме).
    {
        TrackMap& m = trackMaps[7];
        m.name = "WRISTWATCH";
        m.desc = "Boost arrows";
        const float k = 282.0f / 976.0f;
        auto L = [k](float x, float y) { return Vec2{ 180.0f + (x - 563.0f) * k, 84.0f + (y - 250.0f) * k }; };
        auto Conv = [&](std::vector<Vec2> v) { for (Vec2& p : v) p = L(p.x, p.y); return v; };

        // контур: верх, правая стена с выпуклой дугой, низ, левая стена с дугой
        std::vector<Vec2> body = { { 290, 250 }, { 835, 250 }, { 835, 440 } };
        const float R = 612.0f, cxr = 296.0f, cyr = 730.0f;               // правая дуга: центр слева
        float a0 = std::atan2(440.0f - cyr, 835.0f - cxr), a1 = std::atan2(1020.0f - cyr, 835.0f - cxr);
        for (int i = 1; i < 20; ++i) {
            float a = a0 + (a1 - a0) * i / 20.0f;
            body.push_back({ cxr + std::cos(a) * R, cyr + std::sin(a) * R });
        }
        body.push_back({ 835, 1020 });
        body.push_back({ 835, 1226 });
        body.push_back({ 290, 1226 });
        body.push_back({ 290, 1020 });
        const float cxl = 829.0f;                                          // левая дуга: центр справа
        float b0 = std::atan2(1020.0f - cyr, 290.0f - cxl), b1 = std::atan2(440.0f - cyr, 290.0f - cxl);
        if (b1 < b0) b1 += 2.0f * SDL_PI_F;
        // идём от нижней точки к верхней через левую сторону (угол ~180 градусов)
        for (int i = 1; i < 20; ++i) {
            float a = b0 + (b1 - b0) * i / 20.0f;
            body.push_back({ cxl + std::cos(a) * R, cyr + std::sin(a) * R });
        }
        body.push_back({ 290, 440 });
        m.loops.push_back(Conv(body));

        std::vector<Vec2> isl;                                             // овальный остров
        for (int i = 0; i < 48; ++i) {
            float a = 2.0f * SDL_PI_F * i / 48.0f;
            isl.push_back({ 562.0f + std::cos(a) * 138.0f, 730.0f + std::sin(a) * 193.0f });
        }
        m.loops.push_back(Conv(isl));

        std::vector<Vec2> path;                                            // траектория: эллипс вокруг острова
        for (int i = 0; i < 120; ++i) {
            float a = 2.0f * SDL_PI_F * i / 120.0f;
            path.push_back(L(562.0f + std::cos(a) * 255.0f, 730.0f + std::sin(a) * 330.0f));
        }
        FinalizeMap(m, path, L(720, 963));

        // ускорители: стрелка вдоль направления движения по трассе
        const Vec2 pads[2] = { L(748, 495), L(375, 957) };
        for (const Vec2& pd : pads) {
            int bi = 0; float bd = 1e9f;
            for (int i = 0; i < (int)m.path.size(); ++i) {
                float d = Length(m.path[i].x - pd.x, m.path[i].y - pd.y);
                if (d < bd) { bd = d; bi = i; }
            }
            m.boosts.push_back({ m.path[bi].x, m.path[bi].y, PathHeading(m, bi * m.pathStep) });
        }
    }
}

// ---------- траектория ----------
static Vec2 PathPoint(const TrackMap& m, float s) {
    float L = m.pathLen;
    s = std::fmod(s, L);
    if (s < 0.0f) s += L;
    int N = (int)m.path.size();
    float f = s / m.pathStep;
    int i = (int)f;
    float t = f - i;
    i %= N;
    const Vec2& a = m.path[i];
    const Vec2& b = m.path[(i + 1) % N];
    return { a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t };
}

static float PathHeading(const TrackMap& m, float s) {
    Vec2 p0 = PathPoint(m, s - 6.0f);
    Vec2 p1 = PathPoint(m, s + 6.0f);
    return std::atan2(p1.y - p0.y, p1.x - p0.x);
}

// ====================== Профиль и база данных (SQLite) ======================
// Аккаунты хранятся в SQLite: таблицы users (имя, соль, хеш пароля), records (лучшее время и число
// побед по каждой карте) и meta (последний вошедший пользователь — для автовхода).
// Пароль в открытом виде не хранится: SHA-256 с индивидуальной солью (2000 итераций).
//
// Библиотека SQLite подгружается во время работы (SDL_LoadObject), поэтому при сборке
// ничего линковать не нужно. Если библиотека на устройстве не найдена, игра не падает, а
// использует запасное хранилище — текстовый файл с теми же данными (в профиле видно, что
// включён режим FILE). Чтобы собрать с обычной линковкой SQLite, определите USE_LINKED_SQLITE
// и подключите sqlite3 (-lsqlite3).

static const int   USER_NAME_MIN = 3, USER_NAME_MAX = 16;
static const int   USER_PASS_MIN = 4, USER_PASS_MAX = 22;
static const float NO_TIME  = -1.0f;

struct Profile {
    char  name[24];
    int   wins[MAP_COUNT];
    float best[MAP_COUNT];   // секунды; < 0 — результата ещё нет
    Profile() { Clear(); }
    void Clear() {
        name[0] = 0;
        for (int i = 0; i < MAP_COUNT; ++i) { wins[i] = 0; best[i] = NO_TIME; }
    }
    int TotalWins() const { int s = 0; for (int i = 0; i < MAP_COUNT; ++i) s += wins[i]; return s; }
};

static Profile me;
static int PlayerTotalWins() { return me.TotalWins(); }
static bool    loggedIn = false;

// Время текущей гонки и результат для экрана итога
static float raceTime = 0.0f;
static bool  newBest  = false;

// Кнопка профиля в меню
static const float PROF_X = 24.0f, PROF_Y = 543.0f, PROF_W = 312.0f, PROF_H = 40.0f;
// Кнопка гаража — под кнопкой профиля
static const float GARAGE_X = 24.0f, GARAGE_Y = 591.0f, GARAGE_W = 312.0f, GARAGE_H = 40.0f;

static void FormatTime(float t, char* buf, size_t n) {
    if (t < 0.0f) { SDL_snprintf(buf, n, "--:--.-"); return; }
    int m = (int)(t / 60.0f);
    float s = t - m * 60.0f;
    SDL_snprintf(buf, n, "%d:%04.1f", m, s);
}

static bool ValidName(const char* s) {
    int n = (int)SDL_strlen(s);
    if (n < USER_NAME_MIN || n > USER_NAME_MAX) return false;
    for (int i = 0; i < n; ++i) {
        unsigned char c = (unsigned char)s[i];
        if (!(std::isalnum(c) || c == '_' || c == '-')) return false;
    }
    return true;
}

// ---------- SHA-256 ----------
namespace sha {
static const Uint32 K[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};
static inline Uint32 ror(Uint32 x, int n) { return (x >> n) | (x << (32 - n)); }

static void Hash(const unsigned char* d, size_t n, unsigned char out[32]) {
    Uint32 h[8] = { 0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19 };
    std::vector<unsigned char> m(d, d + n);
    m.push_back(0x80);
    while (m.size() % 64 != 56) m.push_back(0);
    Uint64 bits = (Uint64)n * 8;
    for (int i = 7; i >= 0; --i) m.push_back((unsigned char)(bits >> (i * 8)));

    for (size_t off = 0; off < m.size(); off += 64) {
        Uint32 w[64];
        for (int i = 0; i < 16; ++i)
            w[i] = ((Uint32)m[off + i * 4] << 24) | ((Uint32)m[off + i * 4 + 1] << 16) |
                   ((Uint32)m[off + i * 4 + 2] << 8) | (Uint32)m[off + i * 4 + 3];
        for (int i = 16; i < 64; ++i) {
            Uint32 s0 = ror(w[i - 15], 7) ^ ror(w[i - 15], 18) ^ (w[i - 15] >> 3);
            Uint32 s1 = ror(w[i - 2], 17) ^ ror(w[i - 2], 19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16] + s0 + w[i - 7] + s1;
        }
        Uint32 a = h[0], b = h[1], c = h[2], dd = h[3], e = h[4], f = h[5], g = h[6], hh = h[7];
        for (int i = 0; i < 64; ++i) {
            Uint32 S1 = ror(e, 6) ^ ror(e, 11) ^ ror(e, 25);
            Uint32 ch = (e & f) ^ (~e & g);
            Uint32 t1 = hh + S1 + ch + K[i] + w[i];
            Uint32 S0 = ror(a, 2) ^ ror(a, 13) ^ ror(a, 22);
            Uint32 mj = (a & b) ^ (a & c) ^ (b & c);
            Uint32 t2 = S0 + mj;
            hh = g; g = f; f = e; e = dd + t1; dd = c; c = b; b = a; a = t1 + t2;
        }
        h[0] += a; h[1] += b; h[2] += c; h[3] += dd; h[4] += e; h[5] += f; h[6] += g; h[7] += hh;
    }
    for (int i = 0; i < 8; ++i) {
        out[i * 4]     = (unsigned char)(h[i] >> 24);
        out[i * 4 + 1] = (unsigned char)(h[i] >> 16);
        out[i * 4 + 2] = (unsigned char)(h[i] >> 8);
        out[i * 4 + 3] = (unsigned char)(h[i]);
    }
}

static std::string Hex(const unsigned char* d, size_t n) {
    static const char* hx = "0123456789abcdef";
    std::string s;
    for (size_t i = 0; i < n; ++i) { s += hx[d[i] >> 4]; s += hx[d[i] & 15]; }
    return s;
}
} // namespace sha

static std::string PasswordHash(const std::string& salt, const std::string& pass) {
    std::string first = salt + ":" + pass;
    unsigned char d[32];
    sha::Hash((const unsigned char*)first.data(), first.size(), d);
    for (int i = 0; i < 2000; ++i) {
        std::vector<unsigned char> buf(d, d + 32);
        buf.insert(buf.end(), salt.begin(), salt.end());
        sha::Hash(buf.data(), buf.size(), d);
    }
    return sha::Hex(d, 32);
}

static std::string MakeSalt() {
    unsigned char b[8];
    for (int i = 0; i < 8; i += 4) {
        Uint32 r = SDL_rand_bits();
        b[i] = (unsigned char)r; b[i + 1] = (unsigned char)(r >> 8);
        b[i + 2] = (unsigned char)(r >> 16); b[i + 3] = (unsigned char)(r >> 24);
    }
    return sha::Hex(b, 8);
}

enum AuthResult { AUTH_OK = 0, AUTH_EXISTS, AUTH_NOUSER, AUTH_BADPASS, AUTH_ERROR };

// ---------- SQLite, подгружаемая динамически ----------
typedef int (*fn_open)(const char*, void**);
typedef int (*fn_close)(void*);
typedef int (*fn_exec)(void*, const char*, void*, void*, char**);
typedef int (*fn_prepare)(void*, const char*, int, void**, const char**);
typedef int (*fn_bind_text)(void*, int, const char*, int, void (*)(void*));
typedef int (*fn_bind_int)(void*, int, int);
typedef int (*fn_bind_double)(void*, int, double);
typedef int (*fn_step)(void*);
typedef int (*fn_col_int)(void*, int);
typedef double (*fn_col_double)(void*, int);
typedef const unsigned char* (*fn_col_text)(void*, int);
typedef int (*fn_finalize)(void*);

struct SqliteApi {
    void* db = nullptr;
    fn_open open = nullptr;
    fn_close close = nullptr;
    fn_exec exec = nullptr;
    fn_prepare prepare = nullptr;
    fn_bind_text bind_text = nullptr;
    fn_bind_int bind_int = nullptr;
    fn_bind_double bind_double = nullptr;
    fn_step step = nullptr;
    fn_col_int col_int = nullptr;
    fn_col_double col_double = nullptr;
    fn_col_text col_text = nullptr;
    fn_finalize finalize = nullptr;
};
static SqliteApi sq;
static SDL_SharedObject* sqliteLib = nullptr;
static bool dbSqlite = false;            // true — работаем через SQLite, false — запасной файл
static std::string dbFileDir;

static bool SqliteLoadApi() {
#if defined(USE_LINKED_SQLITE)
    sq.open = (fn_open)sqlite3_open;
    sq.close = (fn_close)sqlite3_close;
    sq.exec = (fn_exec)sqlite3_exec;
    sq.prepare = (fn_prepare)sqlite3_prepare_v2;
    sq.bind_text = (fn_bind_text)sqlite3_bind_text;
    sq.bind_int = (fn_bind_int)sqlite3_bind_int;
    sq.bind_double = (fn_bind_double)sqlite3_bind_double;
    sq.step = (fn_step)sqlite3_step;
    sq.col_int = (fn_col_int)sqlite3_column_int;
    sq.col_double = (fn_col_double)sqlite3_column_double;
    sq.col_text = (fn_col_text)sqlite3_column_text;
    sq.finalize = (fn_finalize)sqlite3_finalize;
    return true;
#else
    const char* names[] = { "libsqlite3.so", "libsqlite3.so.0", "libsqlite.so",
                            "sqlite3.dll", "libsqlite3.dylib", "libsqlite3.0.dylib" };
    for (const char* n : names) {
        sqliteLib = SDL_LoadObject(n);
        if (sqliteLib) break;
    }
    if (!sqliteLib) return false;
    sq.open = (fn_open)SDL_LoadFunction(sqliteLib, "sqlite3_open");
    sq.close = (fn_close)SDL_LoadFunction(sqliteLib, "sqlite3_close");
    sq.exec = (fn_exec)SDL_LoadFunction(sqliteLib, "sqlite3_exec");
    sq.prepare = (fn_prepare)SDL_LoadFunction(sqliteLib, "sqlite3_prepare_v2");
    sq.bind_text = (fn_bind_text)SDL_LoadFunction(sqliteLib, "sqlite3_bind_text");
    sq.bind_int = (fn_bind_int)SDL_LoadFunction(sqliteLib, "sqlite3_bind_int");
    sq.bind_double = (fn_bind_double)SDL_LoadFunction(sqliteLib, "sqlite3_bind_double");
    sq.step = (fn_step)SDL_LoadFunction(sqliteLib, "sqlite3_step");
    sq.col_int = (fn_col_int)SDL_LoadFunction(sqliteLib, "sqlite3_column_int");
    sq.col_double = (fn_col_double)SDL_LoadFunction(sqliteLib, "sqlite3_column_double");
    sq.col_text = (fn_col_text)SDL_LoadFunction(sqliteLib, "sqlite3_column_text");
    sq.finalize = (fn_finalize)SDL_LoadFunction(sqliteLib, "sqlite3_finalize");
    return sq.open && sq.close && sq.exec && sq.prepare && sq.bind_text && sq.bind_int &&
           sq.bind_double && sq.step && sq.col_int && sq.col_double && sq.col_text && sq.finalize;
#endif
}

// Обёртка над prepared statement
struct Stmt {
    void* s = nullptr;
    explicit Stmt(const char* sql) {
        if (sq.prepare(sq.db, sql, -1, &s, nullptr) != 0) s = nullptr;
    }
    ~Stmt() { if (s) sq.finalize(s); }
    Stmt(const Stmt&) = delete;
    Stmt& operator=(const Stmt&) = delete;
    Stmt& txt(int i, const char* v) {
        if (s) sq.bind_text(s, i, v, -1, (void (*)(void*))(intptr_t)-1);   // SQLITE_TRANSIENT
        return *this;
    }
    Stmt& num(int i, int v)    { if (s) sq.bind_int(s, i, v); return *this; }
    Stmt& dbl(int i, double v) { if (s) sq.bind_double(s, i, v); return *this; }
    bool row()  { return s && sq.step(s) == 100; }   // SQLITE_ROW
    bool done() { return s && sq.step(s) == 101; }   // SQLITE_DONE
    int ci(int c)       { return sq.col_int(s, c); }
    double cd(int c)    { return sq.col_double(s, c); }
    std::string ct(int c) {
        const unsigned char* p = sq.col_text(s, c);
        return p ? std::string((const char*)p) : std::string();
    }
};

static bool SqliteOpen(const std::string& path) {
    if (!SqliteLoadApi()) return false;
    if (sq.open(path.c_str(), &sq.db) != 0 || !sq.db) return false;
    const char* schema =
        "CREATE TABLE IF NOT EXISTS users("
        " id INTEGER PRIMARY KEY AUTOINCREMENT,"
        " name TEXT NOT NULL UNIQUE COLLATE NOCASE,"
        " salt TEXT NOT NULL, hash TEXT NOT NULL);"
        "CREATE TABLE IF NOT EXISTS records("
        " user_id INTEGER NOT NULL, map_idx INTEGER NOT NULL,"
        " best_time REAL NOT NULL DEFAULT 1e9, wins INTEGER NOT NULL DEFAULT 0,"
        " PRIMARY KEY(user_id, map_idx));"
        "CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY, v TEXT);";
    if (sq.exec(sq.db, schema, nullptr, nullptr, nullptr) != 0) return false;
    return true;
}

// Читает пользователя и его рекорды. salt/hash можно не запрашивать (nullptr)
static bool SqlLoadUser(const char* name, Profile& out, std::string* salt, std::string* hash) {
    Stmt q("SELECT id, name, salt, hash FROM users WHERE name = ?1 COLLATE NOCASE");
    q.txt(1, name);
    if (!q.row()) return false;
    int id = q.ci(0);
    Profile p;
    SDL_strlcpy(p.name, q.ct(1).c_str(), sizeof(p.name));
    if (salt) *salt = q.ct(2);
    if (hash) *hash = q.ct(3);

    Stmt r("SELECT map_idx, best_time, wins FROM records WHERE user_id = ?1");
    r.num(1, id);
    while (r.row()) {
        int m = r.ci(0);
        if (m < 0 || m >= MAP_COUNT) continue;
        double t = r.cd(1);
        p.best[m] = (t < 1.0e8) ? (float)t : NO_TIME;
        p.wins[m] = r.ci(2);
    }
    out = p;
    return true;
}

// ---------- запасное хранилище (если SQLite недоступна): текстовый файл ----------
struct FUser {
    std::string name, salt, hash;
    int wins[MAP_COUNT];
    float best[MAP_COUNT];
};
static std::vector<FUser> fUsers;
static std::string fLast;
static std::vector<std::pair<std::string, int>> fCars;   // цвет машины по имени игрока

static std::string FilePath() { return dbFileDir + "racer_users.txt"; }

static void FileLoad() {
    fUsers.clear();
    fLast.clear();
    fCars.clear();
    size_t sz = 0;
    char* buf = (char*)SDL_LoadFile(FilePath().c_str(), &sz);
    if (!buf) return;
    std::istringstream in(std::string(buf, sz));
    SDL_free(buf);
    std::string line;
    while (std::getline(in, line)) {
        std::istringstream ls(line);
        std::string tag;
        ls >> tag;
        if (tag == "L") {
            ls >> fLast;
        } else if (tag == "C") {
            std::string cn;
            int cc = 0;
            if (ls >> cn >> cc) fCars.push_back({ cn, cc });
        } else if (tag == "U") {
            FUser u;
            ls >> u.name >> u.salt >> u.hash;
            // дальше: K чисел побед и K чисел лучших времён (K — число карт на момент записи).
            // Читаем всё и раскладываем по текущим картам, так что новые карты не ломают старые файлы.
            std::vector<double> nums;
            double v;
            while (ls >> v) nums.push_back(v);
            int K = (int)nums.size() / 2;
            for (int i = 0; i < MAP_COUNT; ++i) {
                u.wins[i] = (i < K) ? (int)nums[i] : 0;
                u.best[i] = (i < K) ? (float)nums[K + i] : NO_TIME;
            }
            if (!u.name.empty() && !u.hash.empty()) fUsers.push_back(u);
        }
    }
}

static void FileSave() {
    std::string out;
    char tmp[64];
    for (const FUser& u : fUsers) {
        out += "U " + u.name + " " + u.salt + " " + u.hash;
        for (int i = 0; i < MAP_COUNT; ++i) { SDL_snprintf(tmp, sizeof(tmp), " %d", u.wins[i]); out += tmp; }
        for (int i = 0; i < MAP_COUNT; ++i) { SDL_snprintf(tmp, sizeof(tmp), " %.3f", u.best[i]); out += tmp; }
        out += "\n";
    }
    for (const auto& c : fCars) {
        SDL_snprintf(tmp, sizeof(tmp), " %d", c.second);
        out += "C " + c.first + tmp + "\n";
    }
    if (!fLast.empty()) out += "L " + fLast + "\n";
    SDL_SaveFile(FilePath().c_str(), out.data(), out.size());
}

static FUser* FileFind(const char* name) {
    for (FUser& u : fUsers)
        if (SDL_strcasecmp(u.name.c_str(), name) == 0) return &u;
    return nullptr;
}

static void FileToProfile(const FUser& u, Profile& out) {
    Profile p;
    SDL_strlcpy(p.name, u.name.c_str(), sizeof(p.name));
    for (int i = 0; i < MAP_COUNT; ++i) { p.wins[i] = u.wins[i]; p.best[i] = u.best[i]; }
    out = p;
}

// ---------- общий интерфейс ----------
static void DbInit() {
    SDL_srand((Uint64)SDL_GetPerformanceCounter() ^ SDL_GetTicksNS());
    char* pref = SDL_GetPrefPath("circleracer", "circleracer");
    if (pref) { dbFileDir = pref; SDL_free(pref); }

    dbSqlite = SqliteOpen(dbFileDir + "racer.db");
    if (!dbSqlite) {
        SDL_Log("SQLite not available - using file storage");
        FileLoad();
    }
}

static void DbClose() {
    if (dbSqlite && sq.db) { sq.close(sq.db); sq.db = nullptr; }
    if (sqliteLib) { SDL_UnloadObject(sqliteLib); sqliteLib = nullptr; }
}

static AuthResult DbRegister(const char* name, const char* pass) {
    std::string salt = MakeSalt();
    std::string hash = PasswordHash(salt, pass);
    if (dbSqlite) {
        Profile tmp;
        if (SqlLoadUser(name, tmp, nullptr, nullptr)) return AUTH_EXISTS;
        Stmt ins("INSERT INTO users(name, salt, hash) VALUES(?1, ?2, ?3)");
        ins.txt(1, name).txt(2, salt.c_str()).txt(3, hash.c_str());
        return ins.done() ? AUTH_OK : AUTH_ERROR;
    }
    if (FileFind(name)) return AUTH_EXISTS;
    FUser u;
    u.name = name; u.salt = salt; u.hash = hash;
    for (int i = 0; i < MAP_COUNT; ++i) { u.wins[i] = 0; u.best[i] = NO_TIME; }
    fUsers.push_back(u);
    FileSave();
    return AUTH_OK;
}

static AuthResult DbLogin(const char* name, const char* pass, Profile& out) {
    std::string salt, hash;
    Profile p;
    if (dbSqlite) {
        if (!SqlLoadUser(name, p, &salt, &hash)) return AUTH_NOUSER;
    } else {
        FUser* u = FileFind(name);
        if (!u) return AUTH_NOUSER;
        salt = u->salt; hash = u->hash;
        FileToProfile(*u, p);
    }
    if (PasswordHash(salt, pass) != hash) return AUTH_BADPASS;
    out = p;
    return AUTH_OK;
}

// Загрузка по имени без пароля (автовход)
static bool DbLoadUser(const char* name, Profile& out) {
    if (dbSqlite) return SqlLoadUser(name, out, nullptr, nullptr);
    FUser* u = FileFind(name);
    if (!u) return false;
    FileToProfile(*u, out);
    return true;
}

static void DbRecordWin(const char* name, int map, float t) {
    if (map < 0 || map >= MAP_COUNT) return;
    if (dbSqlite) {
        {
            Stmt ins("INSERT OR IGNORE INTO records(user_id, map_idx, best_time, wins) "
                     "SELECT id, ?2, 1e9, 0 FROM users WHERE name = ?1 COLLATE NOCASE");
            ins.txt(1, name).num(2, map);
            ins.done();
        }
        Stmt upd("UPDATE records SET wins = wins + 1, best_time = MIN(best_time, ?3) "
                 "WHERE map_idx = ?2 AND user_id = (SELECT id FROM users WHERE name = ?1 COLLATE NOCASE)");
        upd.txt(1, name).num(2, map).dbl(3, t);
        upd.done();
        return;
    }
    FUser* u = FileFind(name);
    if (!u) return;
    u->wins[map]++;
    if (u->best[map] < 0.0f || t < u->best[map]) u->best[map] = t;
    FileSave();
}

static void DbSetLast(const char* name) {
    if (dbSqlite) {
        Stmt s("INSERT OR REPLACE INTO meta(k, v) VALUES('last_user', ?1)");
        s.txt(1, name);
        s.done();
        return;
    }
    fLast = name;
    FileSave();
}

static std::string DbGetLast() {
    if (dbSqlite) {
        Stmt s("SELECT v FROM meta WHERE k = 'last_user'");
        if (s.row()) return s.ct(0);
        return std::string();
    }
    return fLast;
}

// Цвет машины игрока хранится отдельно от рекордов: ключ car:<имя> в таблице meta (или строка C в файле)
static std::string CarKey(const char* name) {
    std::string k = "car:";
    for (const char* p = name; *p; ++p) k += (char)std::tolower((unsigned char)*p);
    return k;
}

static void DbSetCar(const char* name, int idx) {
    if (dbSqlite) {
        Stmt s("INSERT OR REPLACE INTO meta(k, v) VALUES(?1, ?2)");
        char val[16];
        SDL_snprintf(val, sizeof(val), "%d", idx);
        s.txt(1, CarKey(name).c_str()).txt(2, val);
        s.done();
        return;
    }
    for (auto& c : fCars)
        if (SDL_strcasecmp(c.first.c_str(), name) == 0) { c.second = idx; FileSave(); return; }
    fCars.push_back({ name, idx });
    FileSave();
}

static int DbGetCar(const char* name) {
    int idx = CAR_COLOR_DEFAULT;
    if (dbSqlite) {
        Stmt s("SELECT v FROM meta WHERE k = ?1");
        s.txt(1, CarKey(name).c_str());
        if (s.row()) idx = SDL_atoi(s.ct(0).c_str());
    } else {
        for (const auto& c : fCars)
            if (SDL_strcasecmp(c.first.c_str(), name) == 0) { idx = c.second; break; }
    }
    bool ok = (idx >= 0 && idx < CAR_COLORS) || (idx >= CAR_FORMULA_BASE && idx < CAR_FORMULA_BASE + FORM_CARS);
    return ok ? idx : CAR_COLOR_DEFAULT;
}

// ---------- ранги: по общему числу побед (гонки с ботом + сетевые) ----------
struct RankTier { const char* name; int need; Uint8 r, g, b; };
static const RankTier RANKS[] = {
    { "BEGINNER",      0, 150, 165, 190 },
    { "SKILLED RACER", 12, 90, 170, 255 },
    { "TOP RACER",    24, 255, 205, 60 },
};
static const int RANK_COUNT = (int)(sizeof(RANKS) / sizeof(RANKS[0]));
static int RankIndex(int wins) {
    int r = 0;
    for (int i = 0; i < RANK_COUNT; ++i) if (wins >= RANKS[i].need) r = i;
    return r;
}
static int rankUpTo = -1;   // >=0: после последней победы получен новый ранг (показываем на итоге гонки)

// Вызывается в момент победы игрока
static void OnPlayerWin() {
    if (!loggedIn) return;
    int m = curMapIdx;
    newBest = (me.best[m] < 0.0f || raceTime < me.best[m]);
    if (newBest) me.best[m] = raceTime;
    int before = RankIndex(me.TotalWins());
    me.wins[m]++;
    DbRecordWin(me.name, m, raceTime);
    int after = RankIndex(me.TotalWins());
    rankUpTo = (after > before) ? after : -1;
}

// ====================== Гонка ======================
static void ResetCar() {
    const TrackMap& m = CurMap();
    float startS = netRace ? netStartS : PLAYER_START_S;
    Vec2 p = PathPoint(m, startS);
    car.x = p.x;
    car.y = p.y;
    car.angle = PathHeading(m, startS);
    car.speed = 0.0f;

    // режим гонки: формульная машина — лучше разгон, тот же максимум, пит-лейн и износ шин
    // (в сетевой гонке тип машины задаёт комната)
    raceFormula = netRace ? netFormula : FormulaMode();
    car.acceleration = raceFormula ? ACCEL_FORMULA : ACCEL_STANDARD;
    car.maxSpeed = CAR_MAX_SPEED_BASE;
    pitNeeded = false;
    pitTimer = 0.0f;
    wearLaps = 0;
    nextPitLap = PIT_EVERY_LAPS;
    lapsHandled = 0;
    botPitTimer = 0.0f;
    botNextPit = PIT_EVERY_LAPS;

    int N = (int)m.path.size();
    carIdx = (int)std::lround(startS / m.pathStep) % N;
    netLaps = 0;
    lapCount = 0;

    steerInput = gasInput = brakeInput = 0.0f;
    wheelAngle = 0.0f;
    steerSmooth = 0.0f;
    sparkPower = 0.0f;
    dustCount = 0;
    rankUpTo = -1;
    boostT = 0.0f;
    botBoostT = 0.0f;

    botDist = 0.0f;
    botLaps = 0;
    raceState = 0;
    finishTimer = 0.0f;
    raceTime = 0.0f;
    newBest = false;
    netFinTime = -1.0f;
    netWinner = 255;
}

static void ClearPointers() {
    for (int i = 0; i < 10; ++i) fingerDown[i] = false;
    steerInput = gasInput = brakeInput = 0.0f;
    wheelAngle = 0.0f;
}

static void GoMenu() {
    training = false;
    if (gameState == STATE_PLAY && raceState != 0) {   // запоминаем итог гонки для меню
        lastResult = raceState;
        lastResultMap = curMapIdx;
    }
    gameState = STATE_MENU;
    inputLock = 0.35f;
    menuSel = curMapIdx;
    menuPress = false;
    ClearPointers();
}

static void StartRace(int idx) {
    idx = std::clamp(idx, 0, MAP_COUNT - 1);
    if (MapLocked(idx)) { menuSel = idx; return; }      // карта ещё закрыта
    netRace = false;
    training = false;
    curMapIdx = std::clamp(idx, 0, MAP_COUNT - 1);
    menuSel = curMapIdx;
    ClearPointers();
    ResetCar();
    gameState = STATE_PLAY;
}

// Обработка касания борта. (wnx,wny) — единичная нормаль, направленная В СТЕНУ.
// Нормальная составляющая скорости гасится, касательная сохраняется:
// чем меньше угол касания и чем больше скорость — тем лучше скольжение.
static void ResolveWallContact(float wnx, float wny, float contactX, float contactY, float dt) {
    float dirSign = (car.speed >= 0.0f) ? 1.0f : -1.0f;
    float vx = std::cos(car.angle) * car.speed;
    float vy = std::sin(car.angle) * car.speed;

    float into = vx * wnx + vy * wny;
    if (into <= 0.0f) return;              // машина уже движется от борта

    float sp = std::abs(car.speed);
    if (sp < 0.01f) return;

    float sinT = std::clamp(into / sp, 0.0f, 1.0f);   // 0 — вдоль борта, 1 — в лоб

    // касательная составляющая скорости
    float tx = vx - into * wnx;
    float ty = vy - into * wny;
    float vt = Length(tx, ty);

    // потеря от удара зависит от угла, плюс лёгкое трение о борт
    vt *= (1.0f - WALL_IMPACT_LOSS * sinT * sinT);   // малые углы почти без потерь
    vt = std::max(0.0f, vt - WALL_SCRAPE * dt);

    if (vt < 1.0f) {
        car.speed = 0.0f;
    } else {
        car.speed = dirSign * vt;

        // плавно разворачиваем нос вдоль борта
        float travelAngle = std::atan2(ty, tx);
        float target = (dirSign > 0.0f) ? travelAngle : travelAngle + SDL_PI_F;
        car.angle += NormalizeAngle(target - car.angle) * std::min(1.0f, WALL_ALIGN_RATE * dt);
    }

    // искры: сильнее при большой скорости скольжения
    sparkPower = std::max(sparkPower, std::min(1.0f, vt / car.maxSpeed + 0.15f));
    sparkX = contactX;
    sparkY = contactY;
}

// Ближайшая к точке (px,py) точка на стенках карты
static float NearestWall(const TrackMap& m, float px, float py, float& qx, float& qy) {
    float bestD2 = 1e18f;
    for (const Seg& s : m.segs) {
        float ex = s.bx - s.ax, ey = s.by - s.ay;
        float l2 = ex * ex + ey * ey;
        float t = (l2 > 1e-9f) ? ((px - s.ax) * ex + (py - s.ay) * ey) / l2 : 0.0f;
        t = std::clamp(t, 0.0f, 1.0f);
        float cx = s.ax + ex * t, cy = s.ay + ey * t;
        float dx = px - cx, dy = py - cy;
        float d2 = dx * dx + dy * dy;
        if (d2 < bestD2) { bestD2 = d2; qx = cx; qy = cy; }
    }
    return std::sqrt(bestD2);
}

// ---------- бот ----------
static void BotPos(float& x, float& y, float& heading) {
    const TrackMap& m = CurMap();
    float s = BOT_START_S + botDist;
    Vec2 p = PathPoint(m, s);
    x = p.x;
    y = p.y;
    heading = PathHeading(m, s);
}

static void UpdateBot(float dt) {
    const TrackMap& m = CurMap();
    if (botPitTimer > 0.0f) {
        // бот в пит-лейне: стоит «за кадром» и потом едет дальше по той же траектории
        botPitTimer = std::max(0.0f, botPitTimer - dt);
    } else {
        botBoostT = std::max(0.0f, botBoostT - dt);
        botDist += (BOT_SPEED + (botBoostT > 0.0f ? BOOST_BONUS : 0.0f)) * dt;
        if (!m.boosts.empty()) {
            float bx, by, bh;
            BotPos(bx, by, bh);
            for (const Vec3& pd : m.boosts)
                if (Length(bx - pd.x, by - pd.y) < BOOST_RADIUS) botBoostT = BOOST_TIME;
        }
        botLaps = (int)std::floor((BOT_START_S + botDist) / m.pathLen);
        // в режиме Formula бот заезжает в пит-лейн тогда же, когда он нужен игроку
        if (raceFormula && botNextPit < TARGET_LAPS && botLaps >= botNextPit) {
            botPitTimer = PIT_DURATION;
            botNextPit += PIT_EVERY_LAPS;
        }
    }
    if (raceState == 0 && botLaps >= TARGET_LAPS) {
        botLaps = TARGET_LAPS;
        raceState = 2;
        finishTimer = 0.0f;
    }
}

// ---------- круги игрока ----------
static void UpdateProgress() {
    const TrackMap& m = CurMap();
    int N = (int)m.path.size();
    // Окно поиска — четверть траектории: на внутренней дорожке в углах «ближайшая точка»
    // траектории перескакивает сразу на много отсчётов; узкое окно терялось, и круги не считались.
    const int WIN = std::max(20, N / 4);

    int best = carIdx;
    float bd = 1e18f;
    for (int k = -WIN; k <= WIN; ++k) {
        int i = ((carIdx + k) % N + N) % N;
        float dx = car.x - m.path[i].x;
        float dy = car.y - m.path[i].y;
        float d2 = dx * dx + dy * dy;
        if (d2 < bd) { bd = d2; best = i; }
    }

    int diff = best - carIdx;
    if (diff < -N / 2) netLaps++;        // пересекли финиш вперёд
    else if (diff > N / 2) netLaps--;    // пересекли финиш назад
    carIdx = best;
    lapCount = std::max(0, netLaps);
}

// ---------- режим FORMULA: износ шин и пит-лейн игрока ----------
static float TyreFactor() {
    return std::max(PIT_MIN_FACTOR, 1.0f - PIT_WEAR_PER_LAP * (float)wearLaps);
}

static void RefreshTyres() {
    car.maxSpeed = CAR_MAX_SPEED_BASE * (raceFormula ? TyreFactor() : 1.0f);
}

// Игрок завершил круг l (1, 2, 3, ...)
static void OnPlayerLap(int l) {
    if (!raceFormula) return;
    // не заехали в пит-лейн — шины стёрлись, макс. скорость падает на 10% за каждый такой круг
    if (pitNeeded) {
        wearLaps++;
        RefreshTyres();
    }
    // после каждых PIT_EVERY_LAPS кругов нужен пит-лейн, но не на последнем круге гонки
    if (l >= nextPitLap && nextPitLap < TARGET_LAPS) {
        pitNeeded = true;
        nextPitLap += PIT_EVERY_LAPS;
    }
}

static bool PitAvailable() {
    return gameState == STATE_PLAY && raceFormula && raceState == 0 && pitNeeded && pitTimer <= 0.0f;
}

// Заезд в пит-лейн: машина исчезает с трассы на PIT_DURATION секунд, шины как новые
static void StartPit() {
    if (!PitAvailable()) return;
    pitNeeded = false;
    pitTimer = PIT_DURATION;
    wearLaps = 0;
    RefreshTyres();
    car.speed = 0.0f;
    steerSmooth = 0.0f;
    sparkPower = 0.0f;
}

static void StartTraining() {
    netRace = false;
    training = true;
    curMapIdx = 0;
    menuSel = 0;
    ClearPointers();
    ResetCar();
    raceFormula = false;
    car.acceleration = ACCEL_STANDARD;
    RefreshTyres();
    trainStep = 0; trainPage = 0; trainHold = 0.0f; trainOk = 0.0f;
    trainFast = false; trainLap0 = 0; trainModal = false;
    gameState = STATE_PLAY;
}

static void TrainingNextStep() {
    ++trainStep;
    trainHold = 0.0f;
    trainOk = 0.0f;
    if (trainStep == 2) trainLap0 = lapCount;
    if (trainStep == 3) {            // Formula: формульная машина, карточки с объяснением
        raceFormula = true;
        car.acceleration = ACCEL_FORMULA;
        pitNeeded = false;
        trainPage = -1;              // сначала полный круг на формульной машине
        trainLap0 = lapCount;
        trainModal = false;
    }
}

// Тап по карточке: следующая страница
static void TrainingTap() {
    if (!trainModal) return;
    if (trainStep == 3) {
        if (trainPage == 0) trainPage = 1;
        else if (trainPage == 1) {
            trainPage = 2;
            trainModal = false;
            pitNeeded = true;        // показываем кнопку PIT
        } else if (trainPage == 3) {
            ExitRace();
        }
    }
}

static void UpdateTraining(float dt) {
    if (!Training() || trainModal) return;
    if (trainOk > 0.0f) {
        trainOk -= dt;
        if (trainOk <= 0.0f) { trainOk = 0.0f; TrainingNextStep(); }
        return;
    }
    switch (trainStep) {
        case 0:   // газ: разгоняемся
            if (gasInput > 0.1f && car.speed > 70.0f) trainHold += dt; else trainHold = std::max(0.0f, trainHold - dt);
            if (trainHold > 0.6f) trainOk = 1.2f;
            break;
        case 1:   // тормоз: разогнаться и затормозить
            if (car.speed > 110.0f) trainFast = true;
            if (trainFast && brakeInput > 0.1f && car.speed < 45.0f) trainOk = 1.2f;
            break;
        case 2:   // руль: проехать круг
            if (lapCount >= trainLap0 + 1) trainOk = 1.2f;
            break;
        case 3:   // Formula: пит-лейн
            if (trainPage == -1 && lapCount >= trainLap0 + 1) { trainPage = 0; trainModal = true; }
            if (trainPage == 2) {
                if (pitTimer > 0.0f) trainHold = 1.0f;                     // заехал в пит-лейн
                else if (trainHold > 0.5f) { trainPage = 3; trainModal = true; }   // выехал — финал
            }
            break;
    }
}

static void UpdatePhysics(float dt) {
    sparkPower = std::max(0.0f, sparkPower - dt * 5.0f);

    if (raceState != 0) {
        finishTimer += dt;
        return;
    }

    // сетевая гонка: сначала общий отсчёт, потом поехали
    if (netRace) {
        if (netCountdown > 0.0f) {
            netCountdown -= dt;
            if (netCountdown <= 0.0f) { netCountdown = 0.0f; netGoTimer = 0.9f; }
            return;
        }
        if (netGoTimer > 0.0f) netGoTimer -= dt;
    } else if (!Training()) {
        UpdateBot(dt);
    }
    if (raceState != 0) return;
    raceTime += dt;

    // игрок в пит-лейне: его нет на трассе (не движется, не сталкивается), время гонки идёт
    if (pitTimer > 0.0f) {
        pitTimer -= dt;
        if (pitTimer <= 0.0f) {
            pitTimer = 0.0f;
            car.speed = 0.0f;
            steerSmooth = 0.0f;
        }
        return;
    }

    const TrackMap& m = CurMap();

    // руль плавно догоняет нужное положение
    steerSmooth += (steerInput - steerSmooth) * std::min(1.0f, STEER_SMOOTH_RATE * dt);

    // на малой скорости руль работает охотнее (минимум 0.6)
    float turnFactor = std::min(1.0f, std::abs(car.speed) / 55.0f * 0.4f + 0.6f);
    car.angle += steerSmooth * car.turnSpeed * turnFactor * dt;

    // мягкая помощь: если руль в нейтрали, нос машины слегка доворачивается вдоль трассы
    if (std::abs(steerInput) < 0.05f && car.speed > 20.0f && sparkPower < 0.1f) {
        float heading = PathHeading(m, carIdx * m.pathStep);
        float diff = NormalizeAngle(heading - car.angle);
        if (std::abs(diff) < 1.2f)   // не мешаем, если машинка развёрнута против трассы
            car.angle += diff * STEER_ASSIST * std::min(1.0f, car.speed / 100.0f) * dt;
    }

    float speedBefore = car.speed;      // для плавного возврата к максимуму после ускорителя
    if (gasInput > 0.01f)
        car.speed += car.acceleration * gasInput * dt;

    if (brakeInput > 0.01f) {
        if (car.speed > 3.0f)
            car.speed -= car.brakeForce * brakeInput * dt;
        else
            car.speed -= car.brakeForce * 0.4f * brakeInput * dt;
    }

    if (std::abs(car.speed) > 0.4f) {
        float fric = car.friction * dt;
        if (car.speed > 0.0f)
            car.speed = std::max(0.0f, car.speed - fric);
        else
            car.speed = std::min(0.0f, car.speed + fric);
    } else {
        car.speed = 0.0f;
    }

    // ускорители: наезд на стрелку — +20 к скорости на 3 секунды, потолок скорости тоже растёт на 20
    boostT = std::max(0.0f, boostT - dt);
    for (const Vec3& pd : CurMap().boosts) {
        if (Length(car.x - pd.x, car.y - pd.y) < BOOST_RADIUS) {
            if (boostT <= 0.0f && car.speed > 0.0f) car.speed += BOOST_BONUS;
            boostT = BOOST_TIME;
        }
    }
    float speedCap = car.maxSpeed + (boostT > 0.0f ? BOOST_BONUS : 0.0f);
    if (car.speed > speedCap) car.speed = std::max(speedCap, std::min(car.speed, speedBefore) - 60.0f * dt);   // после буста плавно возвращаемся к обычному максимуму
    car.speed = std::max(car.speed, -car.maxSpeed * 0.32f);

    float bx, by, bh;
    BotPos(bx, by, bh);

    // Движение мелкими шагами (≤ 4 px), чтобы не пролетать сквозь тонкие стенки
    float move = std::abs(car.speed) * dt;
    int steps = std::max(1, (int)std::ceil(move / 4.0f));
    float sdt = dt / steps;

    for (int st = 0; st < steps; ++st) {
        float prevX = car.x, prevY = car.y;
        car.x += std::cos(car.angle) * car.speed * sdt;
        car.y += std::sin(car.angle) * car.speed * sdt;

        // Столкновение с чужими машинами в сетевой гонке (каждый отодвигает свою машину)
        if (netRace) {
            for (int s = 0; s < NET_MAX_PLAYERS; ++s) {
                if (s == netMySlot) continue;
                const NetCar& o = netCars[s];
                if (!o.present || o.pit || !o.init) continue;
                float ex = car.x - o.x, ey = car.y - o.y;
                float ed = Length(ex, ey);
                const float minGap = 15.0f;
                if (ed < minGap && ed > 0.001f) {
                    car.x = o.x + ex / ed * minGap;
                    car.y = o.y + ey / ed * minGap;
                    car.speed *= 0.995f;
                }
            }
        }

        // Лёгкое столкновение с ботом (отталкивает только игрока); бота в пит-лейне на трассе нет
        else if (botPitTimer <= 0.0f) {
            float ex = car.x - bx, ey = car.y - by;
            float ed = Length(ex, ey);
            const float minGap = 15.0f;
            if (ed < minGap && ed > 0.001f) {
                car.x = bx + ex / ed * minGap;
                car.y = by + ey / ed * minGap;
                car.speed *= 0.995f;
            }
        }

        // Стенки: внешний борт и острова
        for (int it = 0; it < 3; ++it) {
            float qx = 0.0f, qy = 0.0f;
            float d = NearestWall(m, car.x, car.y, qx, qy);
            if (d >= CAR_HALF) break;

            float nx, ny;
            if (d > 1e-3f) {
                nx = (car.x - qx) / d;
                ny = (car.y - qy) / d;
            } else {
                float fx = prevX - car.x, fy = prevY - car.y;
                float fl = Length(fx, fy);
                if (fl < 1e-4f) break;
                nx = fx / fl;
                ny = fy / fl;
            }
            car.x = qx + nx * CAR_HALF;
            car.y = qy + ny * CAR_HALF;
            ResolveWallContact(-nx, -ny, qx, qy, sdt);
        }
    }

    UpdateProgress();

    // события завершения кругов (по максимальному достигнутому кругу — заезд назад ничего не ломает)
    if (Training()) {
        // тренировка: круги не считаются победой, но если пит-лейн проигнорирован — шины изнашиваются
        while (lapsHandled < lapCount) {
            ++lapsHandled;
            if (trainStep == 3 && trainPage == 2 && pitNeeded) { wearLaps++; RefreshTyres(); }
        }
        return;
    }
    while (lapsHandled < lapCount && lapsHandled < TARGET_LAPS) {
        ++lapsHandled;
        OnPlayerLap(lapsHandled);
    }

    if (lapCount >= TARGET_LAPS) {
        if (netRace) {
            // в сети победителя объявляет хост; запоминаем своё время финиша
            if (netFinTime < 0.0f) netFinTime = raceTime;
        } else {
            raceState = 1;
            finishTimer = 0.0f;
            OnPlayerWin();
        }
    }
}

static void UpdateTouchControls() {
    steerInput = 0.0f;
    gasInput   = 0.0f;
    brakeInput = 0.0f;

    for (int i = 0; i < 10; ++i) {
        if (!fingerDown[i]) { fingerOnWheel[i] = false; continue; }

        float px = fingerX[i];
        float py = fingerY[i];

        float dx = px - WHEEL_CX;
        float dy = py - WHEEL_CY;
        float dist = Length(dx, dy);

        // Касание, начатое на руле, продолжает вести руль, даже если палец съехал за край диска.
        // Начать рулить можно только внутри нарисованного диска.
        if (dist <= WHEEL_RADIUS) fingerOnWheel[i] = true;
        if (fingerOnWheel[i]) {
            float angle = std::atan2(dx, -dy);
            steerInput = std::clamp(angle / (SDL_PI_F * 0.85f), -1.0f, 1.0f);
            const float dead = WHEEL_RADIUS * 0.27f;              // мёртвая зона у центра
            if (dist < dead) steerInput *= dist / dead;
            continue;
        }

        // зоны газа и тормоза совпадают с нарисованными кнопками
        if (px >= GAS_X && px <= GAS_X + GAS_W && py >= GAS_Y && py <= GAS_Y + GAS_H) {
            gasInput = 1.0f; continue;
        }
        if (px >= BRAKE_X && px <= BRAKE_X + BRAKE_W && py >= BRAKE_Y && py <= BRAKE_Y + BRAKE_H) {
            brakeInput = 1.0f; continue;
        }
    }
}

// ====================== Отрисовка ======================
static void DrawCircle(float cx, float cy, float r, int segments = 64) {
    for (int i = 0; i < segments; ++i) {
        float a1 = (float)i / segments * 2.0f * SDL_PI_F;
        float a2 = (float)(i + 1) / segments * 2.0f * SDL_PI_F;
        SDL_RenderLine(renderer,
                       cx + std::cos(a1) * r, cy + std::sin(a1) * r,
                       cx + std::cos(a2) * r, cy + std::sin(a2) * r);
    }
}

// Закрашенный круг горизонтальными линиями
static void FillCircle(float cx, float cy, float r, Uint8 cr, Uint8 cg, Uint8 cb, Uint8 ca) {
    SDL_SetRenderDrawColor(renderer, cr, cg, cb, ca);
    for (float dy = -r + 0.5f; dy < r; dy += 1.0f) {
        float half = std::sqrt(std::max(0.0f, r * r - dy * dy));
        SDL_RenderLine(renderer, cx - half, cy + dy, cx + half, cy + dy);
    }
}

static void DrawText(const char* s, float x, float y, float sc, Uint8 r, Uint8 g, Uint8 b) {
    SDL_SetRenderScale(renderer, sc, sc);
    SDL_SetRenderDrawColor(renderer, r, g, b, 255);
    SDL_RenderDebugText(renderer, x / sc, y / sc, s);
    SDL_SetRenderScale(renderer, 1.0f, 1.0f);
}

static float TextWidth(const char* s, float sc) {
    return (float)SDL_strlen(s) * 8.0f * sc;
}

static void DrawTextCentered(const char* s, float cx, float y, float sc, Uint8 r, Uint8 g, Uint8 b) {
    DrawText(s, cx - TextWidth(s, sc) * 0.5f, y, sc, r, g, b);
}

static void DrawButton(float x, float y, float w, float h, const char* label, Uint8 r, Uint8 g, Uint8 b) {
    SDL_SetRenderDrawColor(renderer, r, g, b, 255);
    SDL_FRect box = { x, y, w, h };
    SDL_RenderFillRect(renderer, &box);
    SDL_SetRenderDrawColor(renderer, 230, 235, 245, 255);
    SDL_RenderRect(renderer, &box);
    DrawTextCentered(label, x + w * 0.5f, y + (h - 16.0f) * 0.5f, 2.0f, 255, 255, 255);
}

static void DrawCarProcedural(float cx, float cy, float ang, float w, float h, Uint8 cr, Uint8 cg, Uint8 cb) {
    float cosA = std::cos(ang);
    float sinA = std::sin(ang);
    float hw = w * 0.5f;
    float hh = h * 0.5f;

    // 4 угла кузова
    SDL_FPoint pts[5];
    pts[0].x = cx + (-hw)*cosA - (-hh)*sinA;
    pts[0].y = cy + (-hw)*sinA + (-hh)*cosA;
    pts[1].x = cx + ( hw)*cosA - (-hh)*sinA;
    pts[1].y = cy + ( hw)*sinA + (-hh)*cosA;
    pts[2].x = cx + ( hw)*cosA - ( hh)*sinA;
    pts[2].y = cy + ( hw)*sinA + ( hh)*cosA;
    pts[3].x = cx + (-hw)*cosA - ( hh)*sinA;
    pts[3].y = cy + (-hw)*sinA + ( hh)*cosA;
    pts[4] = pts[0];

    // Кузов
    SDL_SetRenderDrawColor(renderer, cr, cg, cb, 255);
    SDL_RenderLines(renderer, pts, 5);

    // Заливка кузова
    for (float t = -0.88f; t <= 0.88f; t += 0.14f) {
        float lx = cx + t * hw * cosA;
        float ly = cy + t * hw * sinA;
        float dx = -hh * sinA * 0.7f;
        float dy =  hh * cosA * 0.7f;
        SDL_RenderLine(renderer, lx - dx, ly - dy, lx + dx, ly + dy);
    }

    // Белая полоса по центру
    SDL_SetRenderDrawColor(renderer, 240, 240, 240, 255);
    float stripeHalf = hw * 0.7f;
    float sx1 = cx - stripeHalf * cosA;
    float sy1 = cy - stripeHalf * sinA;
    float sx2 = cx + stripeHalf * cosA;
    float sy2 = cy + stripeHalf * sinA;
    SDL_RenderLine(renderer, sx1, sy1, sx2, sy2);
    // чуть толще
    SDL_RenderLine(renderer,
                   sx1 - sinA * 1.2f, sy1 + cosA * 1.2f,
                   sx2 - sinA * 1.2f, sy2 + cosA * 1.2f);

    // Фары (жёлтые)
    SDL_SetRenderDrawColor(renderer, 255, 230, 80, 255);
    float fx = cx + cosA * (hw + 1.0f);
    float fy = cy + sinA * (hw + 1.0f);
    // левая фара
    float lx = fx - sinA * 3.5f;
    float ly = fy + cosA * 3.5f;
    SDL_FRect lightL = { lx - 2.0f, ly - 2.0f, 4.0f, 4.0f };
    SDL_RenderFillRect(renderer, &lightL);
    // правая фара
    float rx = fx + sinA * 3.5f;
    float ry = fy - cosA * 3.5f;
    SDL_FRect lightR = { rx - 2.0f, ry - 2.0f, 4.0f, 4.0f };
    SDL_RenderFillRect(renderer, &lightR);
}

