static void DrawToggle(float x, float y, float w, float h, const char* label, bool sel, float sc) {
    SDL_SetRenderDrawColor(renderer, sel ? 36 : 26, sel ? 84 : 30, sel ? 140 : 44, 255);
    SDL_FRect box = { x, y, w, h };
    SDL_RenderFillRect(renderer, &box);
    if (sel) SDL_SetRenderDrawColor(renderer, 255, 210, 60, 255);
    else     SDL_SetRenderDrawColor(renderer, 90, 98, 120, 255);
    SDL_RenderRect(renderer, &box);
    if (sel) { SDL_FRect b2 = { x + 1, y + 1, w - 2, h - 2 }; SDL_RenderRect(renderer, &b2); }
    DrawTextCentered(label, x + w * 0.5f, y + (h - 8.0f * sc) * 0.5f, sc,
                     sel ? 255 : 190, sel ? 255 : 196, sel ? 255 : 215);
}

static void DrawPanel(float x, float y, float w, float h, bool hot) {
    SDL_SetRenderDrawColor(renderer, hot ? 34 : 24, hot ? 40 : 28, hot ? 58 : 38, 255);
    SDL_FRect box = { x, y, w, h };
    SDL_RenderFillRect(renderer, &box);
    if (hot) SDL_SetRenderDrawColor(renderer, 255, 210, 60, 255);
    else     SDL_SetRenderDrawColor(renderer, 90, 98, 120, 255);
    SDL_RenderRect(renderer, &box);
}

// спрайт машинки носом вверх, высотой h, по центру (cx, cy)
static void DrawSpriteIcon(SDL_Texture* t, float cx, float cy, float h, Uint8 r, Uint8 g, Uint8 b) {
    if (t) {
        float tw = 0.0f, th = 0.0f;
        SDL_GetTextureSize(t, &tw, &th);
        float dw = h * tw / th;
        SDL_FRect d = { cx - dw * 0.5f, cy - h * 0.5f, dw, h };
        SDL_RenderTexture(renderer, t, nullptr, &d);
    } else {
        SDL_SetRenderDrawColor(renderer, r, g, b, 255);
        SDL_FRect d = { cx - h * 0.2f, cy - h * 0.5f, h * 0.4f, h };
        SDL_RenderFillRect(renderer, &d);
    }
}

static void DrawMapPreviewIn(const TrackMap& m, float bx, float by, float bw, float bh, float k) {
    float ox = bx + (bw - 360.0f * k) * 0.5f;
    float oy = by + (bh - 324.0f * k) * 0.5f - 36.0f * k;
    DrawMapPreview(m, ox, oy, k);
}

static void DrawNetMessage(float y) {
    if (netMsg.empty()) return;
    if (netMsgErr) DrawTextCentered(netMsg.c_str(), LOGICAL_W * 0.5f, y, 1.0f, 240, 110, 110);
    else           DrawTextCentered(netMsg.c_str(), LOGICAL_W * 0.5f, y, 1.0f, 110, 230, 130);
}

static bool IsBackKey(const SDL_Event* e) {
    return e->type == SDL_EVENT_KEY_DOWN &&
           (e->key.scancode == SDL_SCANCODE_ESCAPE || e->key.scancode == SDL_SCANCODE_AC_BACK);
}

