static void EnterMode() {
    training = false;
    netOnline = false;
    gameState = STATE_MODE;
    inputLock = 0.35f;
    menuPress = false;
    netRace = false;
    netIpActive = false;
    SDL_StopTextInput(window);
    ClearPointers();
}

static void EnterBotMenu() {
    gameState = STATE_MENU;
    inputLock = 0.35f;
    menuSel = curMapIdx;
    menuPress = false;
    ClearPointers();
}

static void EnterNetList() {
    gameState = STATE_NET_LIST;
    if (netSock >= 0 && netOnline != netSockOnline) NetClose();
    inputLock = 0.3f;
    netRooms.clear();
    netJoining = false;
    netIpActive = false;
    netMsg.clear();
    SDL_StopTextInput(window);
    ClearPointers();
    if (!NetOpen()) {
        NetSetMsg("NETWORK ERROR: CANNOT OPEN SOCKET", true);
        return;
    }
    if (netOnline) {
        // подключение к серверу автоматически: адрес берётся из ONLINE_DEFAULT_SERVER
        const char* e = SDL_getenv("CR_SERVER");     // для тестов на одном компьютере
        SDL_snprintf(onlineSrvText, sizeof(onlineSrvText), "%s", (e && *e) ? e : ONLINE_DEFAULT_SERVER);
        onlinePongAge = 99.0f;
        onlinePingT = 10.0f;
        onlineRetryT = 0.0f;
        if (!onlineSrvText[0] || !OnlineResolve(onlineSrvText)) NetSetMsg("CANNOT FIND THE SERVER", true);
    } else {
        NetRefreshInterfaces();
    }
    netTDiscover = 10.0f;      // первая рассылка сразу
}

static SDL_AppResult HandleModeEvent(const SDL_Event* event, bool pointerDown, float px, float py) {
    if (event->type == SDL_EVENT_KEY_DOWN) {
        switch (event->key.scancode) {
            case SDL_SCANCODE_ESCAPE: return SDL_APP_SUCCESS;
            case SDL_SCANCODE_1: EnterBotMenu(); break;
            case SDL_SCANCODE_2: netOnline = false; EnterNetList(); break;
            case SDL_SCANCODE_3: netOnline = true; EnterNetList(); break;
            case SDL_SCANCODE_4: StartTraining(); break;
            case SDL_SCANCODE_P: uiReturn = STATE_MODE; EnterProfile(); break;
            case SDL_SCANCODE_G: uiReturn = STATE_MODE; EnterGarage(); break;
            default: break;
        }
    }
    if (pointerDown && inputLock <= 0.0f) {
        if (InRect(px, py, MODE_X, MODE_BOT_Y, MODE_W, MODE_CARD_H)) EnterBotMenu();
        else if (InRect(px, py, MODE_X, MODE_NET_Y, MODE_W, MODE_CARD_H)) { netOnline = false; EnterNetList(); }
        else if (InRect(px, py, MODE_X, MODE_ONL_Y, MODE_W, MODE_CARD_H)) { netOnline = true; EnterNetList(); }
        else if (InRect(px, py, MODE_X, MODE_TRAIN_Y, MODE_W, MODE_CARD_H)) StartTraining();
        else if (InRect(px, py, MODE_X, MODE_BTN_Y, MODE_BTN_W, MODE_BTN_H)) { uiReturn = STATE_MODE; EnterProfile(); }
        else if (InRect(px, py, MODE_BTN2_X, MODE_BTN_Y, MODE_BTN_W, MODE_BTN_H)) { uiReturn = STATE_MODE; EnterGarage(); }
    }
    return SDL_APP_CONTINUE;
}

