static const float NL_IP_Y = 68.0f, NL_IP_H = 30.0f, NL_IP_X = 24.0f, NL_IP_W = 206.0f;
static const float NL_FIND_X = 238.0f, NL_FIND_W = 98.0f;
static const float NL_LIST_Y = 114.0f, NL_ROW_H = 50.0f, NL_ROW_GAP = 6.0f;
static const int   NL_ROWS = 5;
static const float NL_CREATE_Y = 426.0f, NL_CREATE_H = 54.0f;
static const float NL_BACK_Y = 492.0f, NL_BACK_H = 46.0f;
static float NetRowY(int i) { return NL_LIST_Y + i * (NL_ROW_H + NL_ROW_GAP); }

static void NetListBack() {
    NetShutdown();
    EnterMode();
}

static SDL_AppResult HandleNetListEvent(const SDL_Event* event, bool pointerDown, float px, float py) {
    char* ipBuf = netIpText;
    int ipCap = 24;
    if (event->type == SDL_EVENT_TEXT_INPUT && netIpActive && !netOnline) {
        int len = (int)SDL_strlen(ipBuf);
        for (const char* p = event->text.text; *p && len < ipCap; ++p) {
            bool ok = (*p >= '0' && *p <= '9') || *p == '.' || *p == ':';
            if (ok) { ipBuf[len++] = *p; ipBuf[len] = 0; }
        }
    } else if (event->type == SDL_EVENT_KEY_DOWN) {
        switch (event->key.scancode) {
            case SDL_SCANCODE_BACKSPACE: {
                int len = (int)SDL_strlen(ipBuf);
                if (netIpActive && len > 0) ipBuf[len - 1] = 0;
                break;
            }
            case SDL_SCANCODE_RETURN: case SDL_SCANCODE_KP_ENTER:
                if (netIpActive && ipBuf[0]) NetFindByIp();
                break;
            case SDL_SCANCODE_ESCAPE: case SDL_SCANCODE_AC_BACK:
                NetListBack();
                break;
            default: break;
        }
    }

    if (pointerDown && inputLock <= 0.0f) {
        if (!netOnline && InRect(px, py, NL_IP_X, NL_IP_Y, NL_IP_W, NL_IP_H)) {
            netIpActive = true;
            ShowKeyboard();
        } else if (!netOnline && InRect(px, py, NL_FIND_X, NL_IP_Y, NL_FIND_W, NL_IP_H)) {
            inputLock = 0.3f;
            NetFindByIp();
        } else if (InRect(px, py, 24.0f, NL_CREATE_Y, 312.0f, NL_CREATE_H)) {
            inputLock = 0.3f;
            netIpActive = false;
            SDL_StopTextInput(window);
            gameState = STATE_NET_CREATE;
            crMap = std::clamp(curMapIdx, 0, MAP_COUNT - 1);
            if (MapLocked(crMap)) crMap = 0;
        } else if (InRect(px, py, 24.0f, NL_BACK_Y, 312.0f, NL_BACK_H)) {
            inputLock = 0.3f;
            NetListBack();
        } else {
            netIpActive = false;
            SDL_StopTextInput(window);
            if (!netJoining) {
                for (int i = 0; i < NL_ROWS && i < (int)netRooms.size(); ++i) {
                    if (InRect(px, py, 24.0f, NetRowY(i), 312.0f, NL_ROW_H)) {
                        inputLock = 0.3f;
                        NetJoinRoom(netRooms[i]);
                        break;
                    }
                }
            }
        }
    }
    return SDL_APP_CONTINUE;
}

static void DrawNetList() {
    DrawTextCentered(netOnline ? "ONLINE" : "LOCAL NETWORK", LOGICAL_W * 0.5f, 14.0f, 2.5f, 255, 255, 255);
    char buf[96];
    if (netOnline) {
        bool up = onlinePongAge < 6.0f;
        if (up) SDL_snprintf(buf, sizeof(buf), "SERVER OK: %d ROOMS, %d PLAYERS", onlineRooms, onlinePlayers);
        else    SDL_snprintf(buf, sizeof(buf), onlineResolved ? "SERVER NOT RESPONDING" : "SERVER NOT SET");
        DrawTextCentered(buf, LOGICAL_W * 0.5f, 44.0f, 1.0f, up ? 110 : 240, up ? 230 : 120, up ? 130 : 110);
    } else {
        if (netLocalIp[0]) SDL_snprintf(buf, sizeof(buf), "YOUR IP: %s", netLocalIp);
        else               SDL_snprintf(buf, sizeof(buf), "NO WI-FI CONNECTION FOUND");
        DrawTextCentered(buf, LOGICAL_W * 0.5f, 44.0f, 1.0f, 150, 160, 185);
    }
    const char* ipShown = netIpText;

    // поле ввода IP хоста (запасной способ найти комнату) — только в локальной сети
    if (!netOnline) {
        SDL_SetRenderDrawColor(renderer, 24, 28, 40, 255);
        SDL_FRect box = { NL_IP_X, NL_IP_Y, NL_IP_W, NL_IP_H };
        SDL_RenderFillRect(renderer, &box);
        if (netIpActive) SDL_SetRenderDrawColor(renderer, 255, 210, 60, 255);
        else             SDL_SetRenderDrawColor(renderer, 90, 98, 120, 255);
        SDL_RenderRect(renderer, &box);
        if (ipShown[0] || netIpActive) {
            std::string t = ipShown;
            if (netIpActive && ((SDL_GetTicks() / 500) % 2 == 0)) t += "_";
            DrawText(t.c_str(), NL_IP_X + 8.0f, NL_IP_Y + 11.0f, 1.0f, 240, 242, 250);
        } else {
            DrawText("HOST IP (OPTIONAL)", NL_IP_X + 8.0f, NL_IP_Y + 11.0f, 1.0f, 100, 108, 130);
        }
        DrawButton(NL_FIND_X, NL_IP_Y, NL_FIND_W, NL_IP_H, "FIND", 30, 90, 150);


    }

    // комнаты
    if (netRooms.empty()) {
        int dots = (int)((SDL_GetTicks() / 400) % 4);
        std::string s = "SEARCHING FOR ROOMS";
        s.append((size_t)dots, '.');
        DrawTextCentered(s.c_str(), LOGICAL_W * 0.5f, NL_LIST_Y + 40.0f, 1.0f, 150, 160, 185);
        DrawTextCentered("CREATE YOUR OWN ROOM OR ASK A", LOGICAL_W * 0.5f, NL_LIST_Y + 70.0f, 1.0f, 110, 118, 140);
        DrawTextCentered("FRIEND TO CREATE ONE", LOGICAL_W * 0.5f, NL_LIST_Y + 84.0f, 1.0f, 110, 118, 140);
    }
    for (int i = 0; i < NL_ROWS && i < (int)netRooms.size(); ++i) {
        const NetRoom& r = netRooms[i];
        bool open = (r.phase == 0 && r.curP < r.maxP);
        float y = NetRowY(i);
        DrawPanel(24.0f, y, 312.0f, NL_ROW_H, open);
        DrawText(r.host, 36.0f, y + 8.0f, 1.5f, open ? 255 : 150, open ? 255 : 155, open ? 255 : 170);
        std::string line = r.formula ? "FORMULA" : "STANDARD";
        line += "  ";
        line += trackMaps[std::clamp(r.map, 0, MAP_COUNT - 1)].name;
        DrawText(line.c_str(), 36.0f, y + 30.0f, 1.0f, 150, 160, 185);
        SDL_snprintf(buf, sizeof(buf), "%d/%d", r.curP, r.maxP);
        DrawText(buf, 336.0f - 12.0f - TextWidth(buf, 2.0f), y + 8.0f, 2.0f, open ? 110 : 120, open ? 230 : 124, open ? 130 : 140);
        const char* st = r.phase != 0 ? "IN RACE" : (r.curP >= r.maxP ? "FULL" : "TAP TO JOIN");
        DrawText(st, 336.0f - 12.0f - TextWidth(st, 1.0f), y + 30.0f, 1.0f, open ? 255 : 120, open ? 210 : 124, open ? 60 : 140);
    }

    DrawButton(24.0f, NL_CREATE_Y, 312.0f, NL_CREATE_H, "CREATE ROOM", 30, 120, 50);
    DrawButton(24.0f, NL_BACK_Y, 312.0f, NL_BACK_H, "BACK", 90, 40, 40);
    DrawNetMessage(556.0f);
    DrawTextCentered(netOnline ? "PLAY WITH ANYONE VIA THE INTERNET" : "ALL PLAYERS MUST BE ON THE SAME WI-FI", LOGICAL_W * 0.5f, 590.0f, 1.0f, 100, 108, 130);
}

// ====================== Создание комнаты ======================
static const float CR_TYPE_Y = 84.0f, CR_TYPE_H = 40.0f;
static const float CR_PL_LABEL_Y = 138.0f, CR_PL_Y = 156.0f, CR_PL_H = 40.0f;
static const float CR_MAP_LABEL_Y = 210.0f, CR_MAP_Y = 228.0f, CR_MAP_H = 36.0f, CR_MAP_GAP = 8.0f;
static const float CR_PREV_Y = 360.0f, CR_PREV_H = 136.0f;
static const float CR_OK_Y = 504.0f, CR_OK_H = 50.0f, CR_BACK_Y = 564.0f, CR_BACK_H = 44.0f;
static float CrColX(int c) { return 24.0f + c * 108.0f; }
static float CrMapY(int row) { return CR_MAP_Y + row * (CR_MAP_H + CR_MAP_GAP); }

static SDL_AppResult HandleNetCreateEvent(const SDL_Event* event, bool pointerDown, float px, float py) {
    if (IsBackKey(event)) { gameState = STATE_NET_LIST; inputLock = 0.3f; return SDL_APP_CONTINUE; }
    if (pointerDown && inputLock <= 0.0f) {
        bool acted = true;
        if (InRect(px, py, 24.0f, CR_TYPE_Y, 150.0f, CR_TYPE_H)) crType = 0;
        else if (InRect(px, py, 186.0f, CR_TYPE_Y, 150.0f, CR_TYPE_H)) crType = 1;
        else if (InRect(px, py, 24.0f, CR_OK_Y, 312.0f, CR_OK_H)) {
            NetCreateRoom();
            if (gameState == STATE_NET_CREATE) { /* ошибка сокета: остаёмся здесь с сообщением */ }
        }
        else if (InRect(px, py, 24.0f, CR_BACK_Y, 312.0f, CR_BACK_H)) { gameState = STATE_NET_LIST; }
        else {
            acted = false;
            for (int c = 0; c < 3; ++c)
                if (InRect(px, py, CrColX(c), CR_PL_Y, 96.0f, CR_PL_H)) { crPlayers = 2 + c; acted = true; }
            for (int i = 0; i < MAP_COUNT; ++i)
                if (InRect(px, py, CrColX(i % 3), CrMapY(i / 3), 96.0f, CR_MAP_H)) {
                    acted = true;
                    if (MapLocked(i)) NetSetMsg("MAP LOCKED: REACH SKILLED RACER (12 WINS)", true);
                    else crMap = i;
                }
        }
        if (acted) inputLock = 0.25f;
    }
    return SDL_APP_CONTINUE;
}

static void DrawNetCreate() {
    DrawTextCentered("CREATE ROOM", LOGICAL_W * 0.5f, 18.0f, 3.0f, 255, 255, 255);
    DrawTextCentered("RACE TYPE", LOGICAL_W * 0.5f, 66.0f, 1.0f, 170, 180, 205);
    DrawToggle(24.0f, CR_TYPE_Y, 150.0f, CR_TYPE_H, "STANDARD", crType == 0, 1.5f);
    DrawToggle(186.0f, CR_TYPE_Y, 150.0f, CR_TYPE_H, "FORMULA", crType == 1, 1.5f);

    DrawTextCentered("PLAYERS", LOGICAL_W * 0.5f, CR_PL_LABEL_Y, 1.0f, 170, 180, 205);
    for (int c = 0; c < 3; ++c) {
        char b[4];
        SDL_snprintf(b, sizeof(b), "%d", 2 + c);
        DrawToggle(CrColX(c), CR_PL_Y, 96.0f, CR_PL_H, b, crPlayers == 2 + c, 2.0f);
    }

    DrawTextCentered("ROUTE", LOGICAL_W * 0.5f, CR_MAP_LABEL_Y, 1.0f, 170, 180, 205);
    for (int i = 0; i < MAP_COUNT; ++i)
    {
        DrawToggle(CrColX(i % 3), CrMapY(i / 3), 96.0f, CR_MAP_H, trackMaps[i].name, crMap == i, 1.0f);
        if (MapLocked(i)) {
            SDL_SetRenderDrawColor(renderer, 18, 20, 30, 255);
            SDL_FRect sh = { CrColX(i % 3) + 1.0f, CrMapY(i / 3) + 1.0f, 94.0f, CR_MAP_H - 2.0f };
            SDL_RenderFillRect(renderer, &sh);
            char lk[16];
            SDL_snprintf(lk, sizeof(lk), "%d WINS", MapUnlockWins(i));
            DrawTextCentered(lk, CrColX(i % 3) + 48.0f, CrMapY(i / 3) + 14.0f, 1.0f, 230, 190, 60);
        }
    }

    DrawMapPreviewIn(trackMaps[std::clamp(crMap, 0, MAP_COUNT - 1)], 90.0f, CR_PREV_Y, 180.0f, CR_PREV_H, 0.42f);

    DrawButton(24.0f, CR_OK_Y, 312.0f, CR_OK_H, "CREATE", 30, 120, 50);
    DrawButton(24.0f, CR_BACK_Y, 312.0f, CR_BACK_H, "BACK", 90, 40, 40);
    DrawNetMessage(614.0f);
}

// ====================== Комната (ожидание игроков) ======================
static const float NR_LEAVE_Y = 566.0f, NR_LEAVE_H = 50.0f;

static void NetLeaveRoom() {
    NetSendGoodbye();
    NetResetSession();
    EnterNetList();
}

static SDL_AppResult HandleNetRoomEvent(const SDL_Event* event, bool pointerDown, float px, float py) {
    if (IsBackKey(event)) { NetLeaveRoom(); return SDL_APP_CONTINUE; }
    if (pointerDown && inputLock <= 0.0f && InRect(px, py, 24.0f, NR_LEAVE_Y, 312.0f, NR_LEAVE_H)) {
        inputLock = 0.3f;
        NetLeaveRoom();
    }
    return SDL_APP_CONTINUE;
}

static SDL_Texture* NetCarTex(int slot, bool formula);

static void DrawNetRoom() {
    DrawTextCentered("ROOM", LOGICAL_W * 0.5f, 16.0f, 3.0f, 255, 255, 255);
    char buf[96];
    if (netRole == NET_HOST) SDL_snprintf(buf, sizeof(buf), "YOUR ROOM");
    else                     SDL_snprintf(buf, sizeof(buf), "ROOM OF %s", netSlots[0].name);
    DrawTextCentered(buf, LOGICAL_W * 0.5f, 50.0f, 1.5f, 255, 210, 60);

    // сведения о комнате
    DrawPanel(24.0f, 76.0f, 312.0f, 104.0f, false);
    const TrackMap& m = trackMaps[std::clamp(netCfgMap, 0, MAP_COUNT - 1)];
    DrawMapPreviewIn(m, 30.0f, 80.0f, 100.0f, 96.0f, 0.26f);
    DrawText("RACE", 142.0f, 88.0f, 1.0f, 150, 160, 185);
    DrawText(netCfgFormula ? "FORMULA" : "STANDARD", 142.0f, 100.0f, 1.5f, 255, 255, 255);
    DrawText("ROUTE", 142.0f, 122.0f, 1.0f, 150, 160, 185);
    DrawText(m.name, 142.0f, 134.0f, 1.5f, 255, 255, 255);
    SDL_snprintf(buf, sizeof(buf), "PLAYERS %d/%d", NetCount(), netCfgMax);
    DrawText(buf, 142.0f, 158.0f, 1.0f, 110, 230, 130);

    if (netRole == NET_HOST && netLocalIp[0] && !netOnline) {
        SDL_snprintf(buf, sizeof(buf), "IP FOR MANUAL JOIN: %s", netLocalIp);
        DrawTextCentered(buf, LOGICAL_W * 0.5f, 188.0f, 1.0f, 130, 140, 165);
    }

    // игроки и их цвета
    for (int i = 0; i < netCfgMax; ++i) {
        float y = 208.0f + i * 62.0f;
        bool used = netSlots[i].used;
        DrawPanel(24.0f, y, 312.0f, 54.0f, used && i == netMySlot);
        SDL_SetRenderDrawColor(renderer, NET_SLOT_RGB[i][0], NET_SLOT_RGB[i][1], NET_SLOT_RGB[i][2], used ? 255 : 90);
        SDL_FRect sw = { 24.0f, y, 6.0f, 54.0f };
        SDL_RenderFillRect(renderer, &sw);
        if (used) {
            SDL_Texture* t = NetCarTex(i, netCfgFormula);
            DrawSpriteIcon(t, 56.0f, y + 27.0f, 40.0f, NET_SLOT_RGB[i][0], NET_SLOT_RGB[i][1], NET_SLOT_RGB[i][2]);
            DrawText(netSlots[i].name, 84.0f, y + 12.0f, 1.5f, 255, 255, 255);
            SDL_snprintf(buf, sizeof(buf), "%s%s%s", NET_SLOT_NAMES[i], i == 0 ? "  HOST" : "", i == netMySlot ? "  YOU" : "");
            DrawText(buf, 84.0f, y + 34.0f, 1.0f, NET_SLOT_RGB[i][0], NET_SLOT_RGB[i][1], NET_SLOT_RGB[i][2]);
        } else {
            DrawText("WAITING FOR PLAYER...", 84.0f, y + 22.0f, 1.0f, 110, 118, 140);
        }
    }

    int dots = (int)((SDL_GetTicks() / 400) % 4);
    std::string st = (NetCount() >= netCfgMax) ? "STARTING" : "WAITING FOR PLAYERS";
    st.append((size_t)dots, '.');
    DrawTextCentered(st.c_str(), LOGICAL_W * 0.5f, 528.0f, 1.5f, 255, 210, 60);
    DrawTextCentered("THE RACE STARTS WHEN THE ROOM IS FULL", LOGICAL_W * 0.5f, 548.0f, 1.0f, 110, 118, 140);
    DrawButton(24.0f, NR_LEAVE_Y, 312.0f, NR_LEAVE_H, netRole == NET_HOST ? "CLOSE ROOM" : "LEAVE", 140, 40, 40);
}

// ====================== SDL Callbacks ======================
SDL_AppResult SDL_AppInit(void** appstate, int argc, char* argv[]) {
    SDL_SetAppMetadata("Circle Racer", "2.2", "com.example.circleracer");

    if (!SDL_Init(SDL_INIT_VIDEO)) {
        SDL_Log("SDL_Init failed: %s", SDL_GetError());
        return SDL_APP_FAILURE;
    }

    Uint32 flags = SDL_WINDOW_RESIZABLE | SDL_WINDOW_HIGH_PIXEL_DENSITY;
#if defined(__ANDROID__) || defined(__IPHONEOS__)
    flags |= SDL_WINDOW_FULLSCREEN;
#endif

    if (!SDL_CreateWindowAndRenderer("Circle Racer", LOGICAL_W, LOGICAL_H, flags, &window, &renderer)) {
        SDL_Log("CreateWindowAndRenderer failed: %s", SDL_GetError());
        return SDL_APP_FAILURE;
    }

    SDL_SetRenderLogicalPresentation(renderer, LOGICAL_W, LOGICAL_H, SDL_LOGICAL_PRESENTATION_LETTERBOX);
    SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);

    LoadCarTextures();
    BuildMaps();
    curMapIdx = 0;
    menuSel = 0;
    ResetCar();
    gameState = STATE_MENU;
    inputLock = 0.2f;

    // база данных и автовход последнего пользователя
    DbInit();
    std::string last = DbGetLast();
    if (!last.empty() && DbLoadUser(last.c_str(), me)) {
        loggedIn = true;
        ApplyCarChoice(DbGetCar(me.name));
        EnterMode();
    } else {
        EnterAuth();
    }
    return SDL_APP_CONTINUE;
}

// Нормированные координаты пальца (0..1 по окну) -> логические координаты игры.
// Учитывает чёрные полосы letterbox, поэтому зона нажатия совпадает с тем, что нарисовано.
static void FingerToLogical(float nx, float ny, float& lx, float& ly) {
    int w = 0, h = 0;
    SDL_GetWindowSize(window, &w, &h);
    if (w <= 0 || h <= 0) { lx = nx * LOGICAL_W; ly = ny * LOGICAL_H; return; }
    SDL_RenderCoordinatesFromWindow(renderer, nx * (float)w, ny * (float)h, &lx, &ly);
}

// Координаты «нажатия» (палец или мышь) в логических единицах. true — если это именно нажатие
static bool GetPointerDown(const SDL_Event* event, float& lx, float& ly) {
    if (event->type == SDL_EVENT_FINGER_DOWN) {
        FingerToLogical(event->tfinger.x, event->tfinger.y, lx, ly);
        return true;
    }
    if (event->type == SDL_EVENT_MOUSE_BUTTON_DOWN) {
        SDL_RenderCoordinatesFromWindow(renderer, event->button.x, event->button.y, &lx, &ly);
        return true;
    }
    return false;
}

// То же для отпускания
static bool GetPointerUp(const SDL_Event* event, float& lx, float& ly) {
    if (event->type == SDL_EVENT_FINGER_UP) {
        FingerToLogical(event->tfinger.x, event->tfinger.y, lx, ly);
        return true;
    }
    if (event->type == SDL_EVENT_MOUSE_BUTTON_UP) {
        SDL_RenderCoordinatesFromWindow(renderer, event->button.x, event->button.y, &lx, &ly);
        return true;
    }
    return false;
}

// Тап в меню: стрелки страниц, кнопка профиля, карты текущей страницы
static void MenuTap(float px, float py) {
    if (PageCount() > 1) {
        if (InRect(px, py, MENU_ARROW_L_X, MENU_ARROW_Y, PAGE_ARROW_W, PAGE_ARROW_H)) { MenuFlip(-1); return; }
        if (InRect(px, py, MENU_ARROW_R_X, MENU_ARROW_Y, PAGE_ARROW_W, PAGE_ARROW_H)) { MenuFlip(1); return; }
    }
    if (InRect(px, py, MENU_MODE_X, MENU_MODE_Y, MENU_MODE_W, MENU_MODE_H)) { EnterMode(); return; }
    if (InRect(px, py, PROF_X, PROF_Y, PROF_W, PROF_H)) { EnterProfile(); return; }
    if (InRect(px, py, GARAGE_X, GARAGE_Y, GARAGE_W, GARAGE_H)) { EnterGarage(); return; }

    int first = MenuPage() * MENU_PAGE_SIZE;
    int last = std::min(MAP_COUNT, first + MENU_PAGE_SIZE);
    for (int i = first; i < last; ++i) {
        if (InRect(px, py, MenuBoxX(), MenuBoxY(i - first), MenuBoxW(), MenuBoxH())) {
            StartRace(i);
            return;
        }
    }
}

SDL_AppResult SDL_AppEvent(void* appstate, SDL_Event* event) {
    if (event->type == SDL_EVENT_QUIT)
        return SDL_APP_SUCCESS;

    float px = 0.0f, py = 0.0f;
    bool pointerDown = GetPointerDown(event, px, py);

    if (gameState == STATE_AUTH)    return HandleAuthEvent(event, pointerDown, px, py);
    if (gameState == STATE_PROFILE) return HandleProfileEvent(event, pointerDown, px, py);
    if (gameState == STATE_GARAGE)  return HandleGarageEvent(event, pointerDown, px, py);
    if (gameState == STATE_MODE)       return HandleModeEvent(event, pointerDown, px, py);
    if (gameState == STATE_NET_LIST)   return HandleNetListEvent(event, pointerDown, px, py);
    if (gameState == STATE_NET_CREATE) return HandleNetCreateEvent(event, pointerDown, px, py);
    if (gameState == STATE_NET_ROOM)   return HandleNetRoomEvent(event, pointerDown, px, py);

    // ---------------- МЕНЮ ----------------
    if (gameState == STATE_MENU) {
        if (event->type == SDL_EVENT_KEY_DOWN) {
            SDL_Scancode sc = event->key.scancode;
            if (sc >= SDL_SCANCODE_1 && sc <= SDL_SCANCODE_9) {
                int idx = (int)(sc - SDL_SCANCODE_1);
                if (idx < MAP_COUNT) StartRace(idx);
            } else {
                switch (sc) {
                    case SDL_SCANCODE_P: EnterProfile(); break;
                    case SDL_SCANCODE_G: EnterGarage(); break;
                    case SDL_SCANCODE_W: case SDL_SCANCODE_UP:
                        menuSel = (menuSel + MAP_COUNT - 1) % MAP_COUNT; break;
                    case SDL_SCANCODE_S: case SDL_SCANCODE_DOWN:
                        menuSel = (menuSel + 1) % MAP_COUNT; break;
                    case SDL_SCANCODE_A: case SDL_SCANCODE_LEFT: case SDL_SCANCODE_PAGEUP:
                        MenuFlip(-1); break;
                    case SDL_SCANCODE_D: case SDL_SCANCODE_RIGHT: case SDL_SCANCODE_PAGEDOWN:
                        MenuFlip(1); break;
                    case SDL_SCANCODE_RETURN: case SDL_SCANCODE_KP_ENTER: case SDL_SCANCODE_SPACE:
                        StartRace(menuSel); break;
                    case SDL_SCANCODE_ESCAPE: case SDL_SCANCODE_AC_BACK:
                        EnterMode(); break;
                    default: break;
                }
            }
        }

        // колесо мыши листает страницы
        if (event->type == SDL_EVENT_MOUSE_WHEEL && event->wheel.y != 0.0f)
            MenuFlip(event->wheel.y > 0.0f ? -1 : 1);

        // нажатие запоминаем, решаем при отпускании: короткое — тап, длинный вертикальный жест — листание
        if (pointerDown && inputLock <= 0.0f) {
            menuPress = true;
            menuPressX = px;
            menuPressY = py;
        }
        float ux = 0.0f, uy = 0.0f;
        if (GetPointerUp(event, ux, uy) && menuPress) {
            menuPress = false;
            if (inputLock <= 0.0f) {
                float dx = ux - menuPressX, dy = uy - menuPressY;
                if (std::abs(dy) > 36.0f && std::abs(dy) > std::abs(dx))
                    MenuFlip(dy < 0.0f ? 1 : -1);               // свайп вверх — следующая страница
                else if (std::abs(dx) < 24.0f && std::abs(dy) < 24.0f)
                    MenuTap(menuPressX, menuPressY);
            }
        }
        return SDL_APP_CONTINUE;
    }

    // ---------------- ГОНКА ----------------
    if (event->type == SDL_EVENT_KEY_DOWN || event->type == SDL_EVENT_KEY_UP) {
        bool down = (event->type == SDL_EVENT_KEY_DOWN);
        switch (event->key.scancode) {
            case SDL_SCANCODE_A: case SDL_SCANCODE_LEFT:
                if (down) steerInput = -1.0f;
                else if (steerInput < 0.0f) steerInput = 0.0f;
                break;
            case SDL_SCANCODE_D: case SDL_SCANCODE_RIGHT:
                if (down) steerInput = 1.0f;
                else if (steerInput > 0.0f) steerInput = 0.0f;
                break;
            case SDL_SCANCODE_W: case SDL_SCANCODE_UP:
                gasInput = down ? 1.0f : 0.0f;
                break;
            case SDL_SCANCODE_S: case SDL_SCANCODE_DOWN:
                brakeInput = down ? 1.0f : 0.0f;
                break;
            case SDL_SCANCODE_R:
                if (down && !netRace) ResetCar();
                break;
            case SDL_SCANCODE_P:
                if (down) StartPit();    // пит-лейн (только Formula, когда он нужен)
                break;
            case SDL_SCANCODE_RETURN: case SDL_SCANCODE_KP_ENTER: case SDL_SCANCODE_SPACE:
                if (down && raceState != 0 && finishTimer > RESULT_SKIP_TIME) ExitRace();
                break;
            case SDL_SCANCODE_ESCAPE: case SDL_SCANCODE_AC_BACK:
                if (down) ExitRace();
                break;
            default: break;
        }
    }

    if (pointerDown && Training() && trainModal) { TrainingTap(); return SDL_APP_CONTINUE; }

    if (pointerDown) {
        // пропуск экрана итога
        if (raceState != 0 && finishTimer > RESULT_SKIP_TIME) {
            ExitRace();
            return SDL_APP_CONTINUE;
        }
        // кнопка MENU
        if (px >= MENUBTN_X && px <= MENUBTN_X + MENUBTN_W &&
            py >= MENUBTN_Y && py <= MENUBTN_Y + MENUBTN_H) {
            ExitRace();
            return SDL_APP_CONTINUE;
        }
        // кнопка PIT (под тормозом) — видна и активна только когда пит-лейн нужен
        if (PitAvailable() && InRect(px, py, PIT_X, PIT_Y, PIT_W, PIT_H)) {
            StartPit();
            return SDL_APP_CONTINUE;
        }
    }

    if (event->type == SDL_EVENT_FINGER_DOWN ||
        event->type == SDL_EVENT_FINGER_MOTION ||
        event->type == SDL_EVENT_FINGER_UP) {

        int id = (int)(event->tfinger.fingerID % 10);
        if (id < 0) id = 0;

        if (event->type == SDL_EVENT_FINGER_DOWN || event->type == SDL_EVENT_FINGER_MOTION) {
            fingerDown[id] = true;
            FingerToLogical(event->tfinger.x, event->tfinger.y, fingerX[id], fingerY[id]);
        } else {
            fingerDown[id] = false;
        }
        UpdateTouchControls();
    }

    if (event->type == SDL_EVENT_MOUSE_BUTTON_DOWN ||
        event->type == SDL_EVENT_MOUSE_BUTTON_UP ||
        event->type == SDL_EVENT_MOUSE_MOTION) {

        float mx, my;
        SDL_GetMouseState(&mx, &my);
        float logicalX, logicalY;
        SDL_RenderCoordinatesFromWindow(renderer, mx, my, &logicalX, &logicalY);

        bool pressed = (SDL_GetMouseState(nullptr, nullptr) & SDL_BUTTON_LMASK) != 0;
        if (pressed) {
            fingerDown[0] = true;
            fingerX[0] = logicalX;
            fingerY[0] = logicalY;
        } else {
            fingerDown[0] = false;
        }
        UpdateTouchControls();
    }

    return SDL_APP_CONTINUE;
}

SDL_AppResult SDL_AppIterate(void* appstate) {
    static Uint64 lastTime = 0;
    Uint64 now = SDL_GetTicks();
    float dt = (now - lastTime) / 1000.0f;
    if (lastTime == 0) dt = 0.016f;
    if (dt > 0.05f) dt = 0.05f;
    lastTime = now;

    if (inputLock > 0.0f) inputLock -= dt;
    if (kbPending > 0.0f) {                       // отложенное открытие клавиатуры на экране входа
        kbPending -= dt;
        if (kbPending <= 0.0f && gameState == STATE_AUTH) ShowKeyboard();
    }

    SDL_SetRenderDrawColor(renderer, 14, 16, 24, 255);
    SDL_RenderClear(renderer);

    NetTick(dt);

    if (gameState == STATE_AUTH) {
        DrawAuth();
    } else if (gameState == STATE_MODE) {
        DrawMode();
    } else if (gameState == STATE_NET_LIST) {
        DrawNetList();
    } else if (gameState == STATE_NET_CREATE) {
        DrawNetCreate();
    } else if (gameState == STATE_NET_ROOM) {
        DrawNetRoom();
    } else if (gameState == STATE_PROFILE) {
        DrawProfile();
    } else if (gameState == STATE_GARAGE) {
        DrawGarage();
    } else if (gameState == STATE_MENU) {
        DrawMenu();
    } else {
        if (!(Training() && trainModal)) UpdatePhysics(dt);
        UpdateTraining(dt);

        // гонка закончилась — запоминаем итог и возвращаемся в меню
        if (raceState != 0 && finishTimer > RESULT_SHOW_TIME) {
            ExitRace();
        } else {
            UpdateDust((Training() && trainModal) ? 0.0f : dt);
            DrawArena();
            DrawDust();
            if (netRace) DrawNetCars();
            else         DrawBot();
            DrawCar();
            DrawSparks();
            DrawControlsUI();
            if (Training()) DrawTrainingUI();
        }
    }

    SDL_RenderPresent(renderer);
    return SDL_APP_CONTINUE;
}

void SDL_AppQuit(void* appstate, SDL_AppResult result) {
    NetShutdown();
    DbClose();
    for (int i = 0; i < CAR_COLORS; ++i)
        if (texCars[i]) SDL_DestroyTexture(texCars[i]);
    if (texBot)    SDL_DestroyTexture(texBot);
    for (int i = 0; i < FORM_CARS; ++i)
        if (texForm[i]) SDL_DestroyTexture(texForm[i]);
    if (texBotForm) SDL_DestroyTexture(texBotForm);
}
